'use strict';
const D=window.REGION_DATA,P=new Map(D.projects.map(p=>[p.id,p])),cache=new Map(),pending=new Map(),main=document.querySelector('#main');
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=v=>v===null||v===undefined?'미확인':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:2});
const link=(p,route='project')=>'#'+route+'/'+encodeURIComponent(p.id),pill=(s,c='original')=>`<span class="pill ${c}">${E(s)}</span>`;
const heading=(t,s)=>`<div class="page-heading illustrated-heading"><img class="section-art" src="assets/${t==='사업 연관정보'?'evidence-network':'evidence-library'}.svg" alt=""><div class="eyebrow">REGIONAL PROJECTS</div><h1>${t}</h1><p>${s}</p></div>`;
const quote=s=>`<div class="quote">${E(s||'자료에 기재된 내용 없음')}</div>`;
const meta=(s,l)=>`<div class="source-meta">${E(s)}<br>${E(l)}</div>`;
const url=u=>/^https?:\/\//i.test(u||'')?E(u):'';
function budgetStatusLabel(s){return ({'원문이관':'자료 기재액','잠정채택':'잠정 집계'})[s]||s||'미확인'}
const budgets=p=>`<div class="budgets">${[['whole','전체 사업비'],['window','2027~2032년 투자액'],['national','해당 기간 국비 요구액']].map(([k,t])=>`<div class="budget-card"><div class="label">${t}</div><strong>${N(p[k])}<span class="unit">${p[k]==null?'':'억원'}</span></strong>${pill(budgetStatusLabel(p[k+'_status']),p[k]==null?'unknown':'neutral')}</div>`).join('')}</div>`;
window.REGION_PROJECT=data=>{cache.set(data.id,data);if(pending.has(data.id)){pending.get(data.id).resolve(data);pending.delete(data.id)}};
function packet(id){if(cache.has(id))return Promise.resolve(cache.get(id));if(pending.has(id))return pending.get(id).promise;let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b});pending.set(id,{promise,resolve,reject});const s=document.createElement('script');s.src='data/projects/'+P.get(id).key+'.js';s.onerror=()=>{pending.delete(id);reject(Error('사업 자료를 불러오지 못했습니다. 새로고침해 주세요.'))};document.head.append(s);return promise}
let sourcesPromise;function sources(){return sourcesPromise??=new Promise((resolve,reject)=>{if(window.REGION_SOURCES)return resolve(window.REGION_SOURCES);let s=document.createElement('script');s.src='data/sources.js';s.onload=()=>resolve(window.REGION_SOURCES);s.onerror=()=>{sourcesPromise=null;reject(Error('공개 자료를 불러오지 못했습니다.'))};document.head.append(s)})}
function evidence(e){return `<article class="evidence-card" id="${E(e.evidence_id)}"><div class="evidence-top"><h3>${E(e.field)}</h3>${pill('원문 기재')}</div><div class="evidence-id">${E(e.evidence_id)}</div>${quote(e.excerpt)}${meta(e.source,e.location)}</article>`}
function publicCard(s,relation){return `<article class="evidence-card"><div class="evidence-top"><h3>${E(s.title)}</h3>${pill('공개자료','public')}</div><div class="source-meta">${E(s.source_id)} · ${E(s.publisher_domain)} · ${E(s.read_level)}</div>${quote(s.excerpt)}${s.direct_fact?quote(s.direct_fact):''}<p class="subtle">${E(relation||s.field_scope||'동일사업 여부 미확인')}</p>${pill('동일사업·재원 관계 미확인','unknown')} ${url(s.url)?`<a class="button" href="${url(s.url)}" target="_blank" rel="noopener noreferrer">공개 출처 열기 ↗</a>`:''}${meta('확인일: '+(s.checked||'미기재'),s.direct_location||'')}</article>`}
function overview(){main.innerHTML=`<section class="hero"><div><div class="eyebrow">REGIONAL DEVELOPMENT PLANS</div><h1>권역별 발전계획,<br>사업과 예산 한눈에</h1><p>7개 권역의 1,312개 사업을 권역·부처·예산 조건으로 조회하고, 사업별 계획과 관련 자료를 확인할 수 있습니다. 검색 결과는 요약표와 함께 엑셀로 내려받을 수 있습니다.</p><div class="actions"><a class="button primary" href="#projects">전체 사업 검색 →</a><a class="button" href="#types">사업구분별 현황 →</a></div></div><figure class="atlas-hero-figure"><img src="assets/connected-regions.svg" alt="지역의 도시와 자연, 문서 자료가 연결되는 개념 일러스트"><figcaption>권역별 주요 사업과 관련 자료</figcaption></figure></section><div class="metrics">${[[1312,'전체 사업','건'],[7,'권역','개'],[19731,'사업 자료','개'],[1773,'공개 참고자료','개']].map(([n,t,u])=>`<div class="metric"><div class="label">${t}</div><strong>${N(n)}</strong><small>${u}</small></div>`).join('')}</div><div class="section-head"><h2><span class="num">01</span>권역별 사업</h2><a href="#projects">전체 보기 →</a></div><div class="region-cards">${D.regions.map(r=>`<a class="region-card" href="${hubLink('region',r.region)}"><img class="region-art" src="assets/region-${D.regions.indexOf(r)}.svg" alt="" loading="lazy"><h3>${E(r.region)}<span class="arrow">↗</span></h3><strong>${N(r.count)}</strong><small>개 사업</small><div class="bar-track"><i style="width:${r.count/Math.max(...D.regions.map(x=>x.count))*100}%"></i></div></a>`).join('')}</div><div class="section-head"><h2><span class="num">02</span>자료 확인 현황을 함께 읽기</h2></div><div class="card">${levelLegend()}<p>원문에 적혀 있다는 사실과 실제 집행·소관 확정은 구분합니다. 공개자료 1,773개에는 기존 일반 참고자료 89개가 포함되어 있습니다. 사업명 문자열 확인 31건도 동일사업 확정을 뜻하지 않습니다.</p><a class="button" href="#method">확인 기준 자세히 보기 →</a></div><div class="section-head"><h2><span class="num">03</span>권역별 금액 기재 현황</h2><small>단위: 억원</small></div><div class="notice">철도 사업을 포함한 전체 1,312건입니다. 각 금액은 분석표에 기재된 숫자의 합이며, 누락·보류 건을 0으로 처리하지 않았습니다. 기간·범위가 다른 사업을 포함하므로 확정 예산 총액으로 해석하지 않습니다.</div><div class="card table-wrap"><table><thead><tr><th>권역</th><th>사업 수</th><th>전체 사업비</th><th>2027~2032 투자액</th><th>기간 국비 요구액</th></tr></thead><tbody>${D.regions.map(r=>`<tr><td>${E(r.region)}</td><td>${r.count}</td>${['whole','window','national'].map(k=>`<td class="num">${N(r[k])}<span class="count-note">금액 미확인 ${r[k+'_missing']}건</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function levelLegend(){return `<div class="legend">${[['original','원문 기재'],['public','공개자료'],['rule','문구 비교'],['unknown','미확인']].map(([c,t])=>`<span><i class="dot ${c}"></i>${t}</span>`).join('')}</div>`}
const CROSS_METRICS=[['count','사업 수'],['whole','전체 사업비'],['window','2027~2032년 투자액'],['national','해당 기간 국비 요구액']];
function regionTypeData(projects,regions){
 const ps=[...new Map(projects.map(p=>[p.id,p])).values()];
 return [...regions,'전체 합계'].map(region=>{const subset=region==='전체 합계'?ps:ps.filter(p=>p.region===region),s=selectionSummarySheets(subset,[]);return {region,cells:[...TYPE_GROUPS.map((name,i)=>({name,rows:s[3].rows.slice(i*3,i*3+3)})),{name:'합계',rows:s[0].rows.slice(0,3)}]}});
}
function regionTypeSheets(projects,regions){
 const data=regionTypeData(projects,regions),headers=['권역',...TYPE_GROUPS,'합계'];
 const sheets=CROSS_METRICS.map(([key,label],i)=>({name:key==='count'?'사업수 비교':label.replace('2027~2032년 ','').replace('해당 기간 ',''),headers,widths:[20,24,24,24,24,26],rows:data.map(r=>[r.region,...r.cells.map(c=>key==='count'?c.rows[0][1]:c.rows[i-1][3])])}));
 sheets.push({name:'금액확인 상세',headers:['권역','사업구분','예산 항목','사업 수','집계 가능 금액 (억원)','금액 포함 건수','잠정 집계 건수 (포함 중)','보류 건수','기타 미확인 건수'],widths:[18,18,30,16,26,20,28,18,23],rows:data.flatMap(r=>r.cells.flatMap(c=>c.rows.map(row=>[r.region,c.name,row[2],row[1],...row.slice(3,8)])))});
 sheets.push({name:'읽기안내',headers:['항목','내용'],widths:[28,110],rows:[['자료 기준일','2026-10-30'],['내보낸 시각',new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' (한국시간)'],['다운로드 범위','7개 권역 전체 비교. 화면에서 선택한 예산 항목과 관계없이 사업 수와 세 가지 예산을 모두 포함합니다.'],['금액 단위','억원. 보류·미확인을 제외한 부분합이며 확정 예산이 아닙니다.'],['공란과 0','확인된 금액이 없는 칸은 빈칸입니다. 실제 기재액 0과 구분합니다. 사업이 없는 칸도 금액은 빈칸이며 사업 수는 0입니다.'],['확인 수준','금액확인 상세 시트에서 보류·기타 미확인 건수를 확인합니다. 잠정 집계는 금액 포함 건수의 일부입니다.'],['합계','사업번호당 1건. 교통 사업은 다른 구분에서 제외합니다. 합계 행·열은 소계이므로 상세 행과 다시 합산하지 않습니다. 예산 항목별로 반복된 사업 수도 합산하지 않습니다.'],['행재정권','원자료의 행재정을 화면에 표시한 이름입니다.'],['교통 범위',TYPE_SCOPE],['금액 범위',TYPE_BUDGET_NOTE]]});return sheets;
}
function regionTypePanel(){return `<section class="card cross-comparison" aria-labelledby="cross-title"><div class="summary-heading"><div><p class="eyebrow">7개 권역 × 4개 사업구분</p><h2 id="cross-title">권역별 사업·예산 비교</h2></div><button class="primary" id="cross-export">비교표 엑셀 ↓</button></div><div class="cross-toolbar"><label>비교 항목<select id="cross-metric">${CROSS_METRICS.map(([key,label])=>`<option value="${key}" ${key==='whole'?'selected':''}>${label}</option>`).join('')}</select></label><span id="cross-unit"></span></div><p class="cross-help">각 칸을 누르면 해당 권역·구분의 사업 목록을 볼 수 있습니다. 비교표는 항상 7개 권역 전체를 보여줍니다.</p><div id="cross-table"></div><p class="cross-help">보류·기타 미확인은 금액에서 제외합니다. 잠정 집계는 포함 금액 중 일부이며, 확인된 금액이 없는 칸은 —로 표시합니다.</p><span id="cross-status" role="status"></span></section>`}
function bindRegionTypePanel(){
 const regions=D.regions.map(r=>r.region),data=regionTypeData(D.projects,regions);
 function draw(){const key=document.querySelector('#cross-metric').value,idx=CROSS_METRICS.findIndex(m=>m[0]===key)-1;document.querySelector('#cross-unit').textContent=key==='count'?'단위: 건 · 사업번호 중복 제거':'단위: 억원 · 보류·미확인 제외 부분합';
 document.querySelector('#cross-table').innerHTML=`<div class="table-wrap"><table class="cross-table"><caption>${E(CROSS_METRICS.find(m=>m[0]===key)[1])} 권역별 비교</caption><thead><tr><th scope="col">권역</th>${[...TYPE_GROUPS,'합계'].map(t=>`<th scope="col">${E(t)}</th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr><th scope="row">${E(r.region)}</th>${r.cells.map(c=>{const q=new URLSearchParams();if(r.region!=='전체 합계')q.set('region',r.region);if(c.name!=='합계')q.set('type',c.name);if(key!=='count')q.set('budget',key);const b=c.rows[Math.max(0,idx)];return `<td><a href="#projects?${E(q.toString())}" aria-label="${E(r.region+' '+c.name+' 사업 보기')}"><strong>${key==='count'?N(b[1])+'건':b[3]===null?'—':N(b[3])}</strong>${key==='count'?'':`<small>사업 ${N(b[1])}건 · 금액 포함 ${N(b[4])}</small><small>잠정 집계 ${N(b[5])}</small><small class="cross-pending">보류 ${N(b[6])} · 미확인 ${N(b[7])}</small>`}</a></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
 document.querySelector('#cross-metric').onchange=draw;draw();
 document.querySelector('#cross-export').onclick=async()=>{const button=document.querySelector('#cross-export'),status=document.querySelector('#cross-status');button.disabled=true;try{const blob=window.AtlasXlsx.workbook(regionTypeSheets(D.projects,regions)),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='권역별_사업구분_비교표_'+new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})+'.xlsx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='사업 수·세 가지 예산 비교표와 금액 확인 상세를 내려받았습니다.'}catch(e){status.textContent='비교표를 만들지 못했습니다. 다시 시도해 주세요.';console.error(e)}finally{button.disabled=false}};
}

const TYPE_GROUPS=['경제권','생활권','행재정권','교통'];
// Reviewed project IDs; broad keyword tags are intentionally not used to reclassify budgets.
const TRANSPORT_RANGES=[['강원권','생활권',100,108],['대경권','생활권',78,78],['대경권','생활권',80,94],['대경권','생활권',121,121],['대경권','생활권',128,128],['동남권','생활권',1,35],['동남권','생활권',47,47],['동남권','생활권',59,59],['전남광주권','생활권',87,106],['전남광주권','생활권',138,138],['전북권','생활권',125,128],['전북권','생활권',141,141],['제주권','생활권',116,124],['제주권','생활권',130,130],['중부권','생활권',149,154],['중부권','생활권',156,157],['중부권','생활권',182,182],['중부권','생활권',193,193],['동남권','경제권',49,49],['전북권','경제권',121,121],['전남광주권','경제권',13,14]];
const TRANSPORT_IDS=new Set(TRANSPORT_RANGES.flatMap(([r,c,a,b])=>Array.from({length:b-a+1},(_,i)=>`${r}-${c}-${String(a+i).padStart(3,'0')}`)));
const TYPE_RETAIN_NOTES={
 '강원권-경제권-099':'청정에너지 사업으로, 사업명의 고속도로를 도로교통 시설로 분류하지 않음.',
 '강원권-생활권-111':'역세권 정주·관광 복합개발. 교통시설만의 금액이 분리되지 않아 원자료 구분 유지.',
 '대경권-생활권-079':'공항 배후 신도시·산업단지 개발. 공항 건설사업과 구분하여 원자료 구분 유지.',
 '동남권-경제권-050':'피지컬AI 실증단지와 기업 유치·제조물류 산업생태계 사업. 운송시설·이동서비스 단독 사업이 아님.',
 '동남권-경제권-053':'에너지 생산·저장·거래와 선박연료 공급망 사업. 교통시설만의 금액으로 분리하지 않음.',
 '동남권-생활권-050':'문화 프로그램·공동 브랜드와 거점 이용권을 결합한 운영사업. 교통 부분의 금액을 별도로 확인하지 못함.',
 '동남권-생활권-051':'국제물류특구·배후권역 개발·첨단복합물류도시 조성의 통합사업. 교통시설·운송서비스 금액이 별도 확인되지 않아 전체를 교통으로 옮기지 않음.',
 '동남권-생활권-056':'문화시설·관광콘텐츠·관광교통 통합패스 사업. 교통 부분의 금액을 별도로 확인하지 못함.',
 '전남광주권-경제권-008':'차량제어·원격운전 부품·시스템 기술개발 및 검증 인프라가 포함된 산업지원 사업.',
 '전남광주권-경제권-011':'자율주행 데이터·사이버보안·기능안전 기술개발과 검증 지원 사업.',
 '전남광주권-경제권-015':'차량 플랫폼·에너지 저장거래·운송 실증 복합사업. 교통 부분의 금액을 분리하지 않음.',
 '전남광주권-생활권-159':'통학버스·택시·셔틀과 기숙사 등을 함께 설계하는 복합 교육지원 사업. 이동지원만의 금액이 별도 확인되지 않아 원자료 구분 유지.',
 '전남광주권-생활권-174':'위기가구 발견·방문·사례관리·병원 동행을 결합한 보건복지 사업. 이동 부분만의 금액을 분리하지 않음.',
 '전남광주권-생활권-178':'충전거점·공유차량과 경로당 에너지 설비·이익공유가 결합된 사업. 교통 부분만의 금액을 분리하지 않음.',
 '중부권-생활권-155':'광역교통청 설립·조직 운영·사무 이관 사업. 시설·이동서비스 중심 집계 범위에서는 원자료 구분 유지.',
 '중부권-생활권-189':'관광 테마노선·전망대·문화공간·쉼터 조성의 복합사업. 교통 부분의 금액을 분리하지 않음.'
};
function projectType(p){return TRANSPORT_IDS.has(p.id)?'교통':p.category==='행재정'?'행재정권':p.category}
function projectTypeReason(p){return TRANSPORT_IDS.has(p.id)?'사업명·요약서 내용에서 교통시설 또는 여객·화물 이동서비스를 확인하여 교통으로 별도 집계.':TYPE_RETAIN_NOTES[p.id]||'교통시설·이동서비스 별도 집계 대상 외 사업으로 원자료 구분 유지.'}
const TYPE_SCOPE='교통시설·이동서비스: 도로·철도·항만·공항, 버스·택시·환승·운임, 이동서비스·교통운영 플랫폼 및 실제 운행 실증. 자동차·모빌리티 부품 산업지원, 조직 신설 단독 사업, 교통 금액을 분리할 수 없는 복합개발은 원자료 구분 유지.';
const TYPE_BUDGET_NOTE='사업 단위 재분류이며 세부 항목의 교통비만 산출한 금액이 아닙니다. 운영 실증에 포함된 기술개발 등은 사업 금액에 함께 포함될 수 있습니다. 사업번호별 중복만 제거하며 서로 다른 사업번호 간 동일 노선·사업의 중복 여부는 별도 확정하지 않았습니다.';
function typeClassificationSheet(ps){return {name:'사업구분내역',headers:['사업번호','사업명','권역','집계 구분 (교통 별도)','원자료 사업 구분','교통 별도 집계','분류 기준','확인 자료','자료 위치','확인한 사업 내용','집계 시 유의사항'],widths:[25,65,15,25,22,20,90,60,35,110,90],rows:ps.map(p=>[p.id,p.title,p.region,projectType(p),p.category,TRANSPORT_IDS.has(p.id)?'포함':'미포함',projectTypeReason(p),p.summary_source,p.summary_location,p.summary_body,TYPE_BUDGET_NOTE])}}
function typeDetail(p){return `<details class="card type-detail"><summary>집계 구분: ${E(projectType(p))} · 원자료 구분: ${E(p.category)}</summary><p>${E(projectTypeReason(p))}</p><p>${E(TYPE_BUDGET_NOTE)}</p>${meta(p.summary_source,p.summary_location)}<a class="button" href="#types">사업구분별 현황 →</a></details>`}
function typeSummaryTable(ps,baseParams=new URLSearchParams()){
 const sheet=selectionSummarySheets(ps,[]).find(s=>s.name==='사업구분별요약');
 const query=type=>{const q=new URLSearchParams(baseParams);q.set('type',type);return '#projects?'+q.toString()};
 const row=(rs,total=false)=>`<tr><th scope="row">${total?'합계':`<a href="${E(query(rs[0][0]))}">${E(rs[0][0])} →</a>`}</th><td class="num">${N(rs[0][1])}건</td>${rs.map(r=>`<td class="num"><strong>${r[3]===null?'—':N(r[3])}</strong><span class="summary-known">금액 포함 ${N(r[4])} · 잠정채택 ${N(r[5])}</span><span class="summary-pending ${r[6]||r[7]?'has-pending':''}">보류 ${N(r[6])} · 기타 미확인 ${N(r[7])}</span></td>`).join('')}</tr>`;
 const totals=selectionSummarySheets(ps,[])[0].rows.slice(0,3);
 return `<div class="table-wrap"><table class="selection-summary-table"><thead><tr><th>사업구분</th><th>사업 수</th><th>전체 사업비 (억원)</th><th>2027~2032년 투자액 (억원)</th><th>해당 기간 국비 요구액 (억원)</th></tr></thead><tbody>${TYPE_GROUPS.map((_,i)=>row(sheet.rows.slice(i*3,i*3+3))).join('')}${row(totals,true)}</tbody></table></div>`;
}
function ministryTypeData(projects,records){
 const ps=[...new Map(projects.map(p=>[p.id,p])).values()],labels=new Map(ps.map(p=>[p.id,new Set()]));records.forEach(r=>{if(labels.has(r.id)&&r.label)labels.get(r.id).add(r.label)});
 const names=[...new Set([...labels.values()].flatMap(s=>[...s]))].sort((a,b)=>a.localeCompare(b,'ko'));
 const table=names.map(name=>({name,cells:regionTypeData(ps.filter(p=>labels.get(p.id).has(name)),[])[0].cells}));
 const subsets=[...TYPE_GROUPS.map(t=>ps.filter(p=>projectType(p)===t)),ps],summaries=subsets.map(sub=>selectionSummarySheets(sub,records)[0].rows);
 const totals=Array.from({length:5},(_,i)=>({name:summaries[4][i*3][0].replace('선택 전체','전체 사업'),cells:subsets.map((_,j)=>({name:[...TYPE_GROUPS,'합계'][j],rows:summaries[j].slice(i*3,i*3+3)}))}));
 const multi=ps.filter(p=>labels.get(p.id).size>1);
 totals.push({name:'복수 부처 기재 사업 · 중복 제거',cells:regionTypeData(multi,[])[0].cells});
 return {ps,labels,table,totals,multi};
}
function ministryTypeSheets(projects,records){
 const d=ministryTypeData(projects,records),heads=['자료 기재 부처',...TYPE_GROUPS,'합계'];
 const sheets=CROSS_METRICS.map(([key,label],i)=>({name:key==='count'?'부처별 사업수':label.replace('2027~2032년 ','').replace('해당 기간 ',''),headers:heads,widths:[34,24,24,24,24,26],rows:d.table.map(r=>[r.name,...r.cells.map(c=>key==='count'?c.rows[0][1]:c.rows[i-1][3])])}));
 const detail=(name,rows)=>({name,headers:['집계 구분','사업구분','예산 항목','사업 수 (건 또는 반복 회)','집계 가능 금액 (억원)','금액 포함 건수','잠정 집계 (포함 중)','보류 건수','기타 미확인 건수'],widths:[44,18,30,26,26,22,26,20,24],rows:rows.flatMap(r=>r.cells.flatMap(c=>c.rows.map(b=>[r.name,c.name,b[2],b[1],...b.slice(3,8)])))});
 sheets.push(detail('중복집계 구분',d.totals),detail('부처별 금액확인',d.table));
 sheets.push({name:'복수부처 사업',headers:['사업번호','사업명','권역','집계 사업구분','원자료 사업구분','서로 다른 부처 표기 수','부처 표기 목록','추가 반복 횟수','전체 사업비 (억원)','전체 사업비 상태','기간 투자액 (억원)','기간 투자액 상태','국비 요구액 (억원)','국비 요구액 상태','요약서 부처 원문','상세서 부처 원문'],widths:[25,65,16,20,20,25,65,23,24,22,24,22,24,22,65,65],rows:d.multi.map(p=>[p.id,p.title,p.region,projectType(p),p.category,d.labels.get(p.id).size,[...d.labels.get(p.id)].join(' · '),d.labels.get(p.id).size-1,p.whole,p.whole_status,p.window,p.window_status,p.national,p.national_status,p.summary_ministry,p.detail_ministry])});
 const ids=new Set(d.ps.map(p=>p.id));sheets.push({name:'부처 원문과 출처',headers:['사업번호','부처 표기','기재 문서','부처 항목 원문','파일','자료 위치','자료번호','상세서 연결 상태'],widths:[25,28,18,75,65,35,24,28],rows:records.filter(r=>ids.has(r.id)).map(r=>[r.id,r.label,r.origin==='summary'?'요약서':'상세서',r.raw,r.source,r.location,r.evidence,r.detail_match])});
 const guide=regionTypeSheets(projects,[]).find(s=>s.name==='읽기안내');guide.rows=guide.rows.filter(r=>!['다운로드 범위','합계'].includes(r[0]));guide.rows.push(['다운로드 범위','전체 사업의 자료 기재 부처별 비교. 화면 예산 항목과 관계없이 세 가지 금액과 사업 수를 모두 포함합니다.'],['원문 부처 기준','요약서·상세서에 기재된 부처 표기 기준. 약칭과 정식 명칭을 합치지 않습니다. 실제 소관 확정이 아닙니다.'],['반복 집계','같은 사업·같은 부처 표기는 문서가 여러 개여도 한 번만 집계합니다. 서로 다른 부처 표기에 걸친 사업은 부처마다 반복되며 사업비를 부처별로 나누어 배분하지 않습니다.'],['추가 반복분','부처별 반복 합계에서 부처 연결 있음 중복 제거 합계를 뺀 값입니다. 실제 중복 재원·추가 예산이 아닙니다.'],['부처 연결 없음','부처별 비교에서 빠지지만 전체 사업 중복 제거 합계에는 포함합니다.'],['복수 부처 기재 사업','서로 다른 부처 표기가 2개 이상인 사업의 중복 제거 집계입니다. 약칭·정식명칭의 차이도 포함되므로 실제 여러 부처의 공동사업으로 확정한 값은 아닙니다.'],['합계 행 읽기','중복집계 구분의 여섯 항목은 서로 겹치는 비교 기준입니다. 항목들을 서로 합산하지 마세요. 예산별 반복되는 사업 수도 합산하지 않습니다.']);sheets.push(guide);return sheets;
}
function ministryTypePage(){
 const d=ministryTypeData(D.projects,ministryRows);
 main.innerHTML=heading('부처별 사업구분 비교','원문에 기재된 부처별로 경제권·생활권·행재정권·교통의 사업 수와 예산을 비교합니다.')+`<div class="notice">요약서·상세서의 부처 표기를 그대로 사용합니다. 약칭·정식 명칭은 합치지 않습니다. 같은 사업은 부처 안에서 한 번, 서로 다른 부처 표기 사이에서는 반복 집계합니다. 사업비를 부처별로 배분한 금액은 아닙니다.</div><div class="card type-controls"><label>비교 항목<select id="ministry-type-metric">${CROSS_METRICS.map(([k,t])=>`<option value="${k}" ${k==='whole'?'selected':''}>${t}</option>`).join('')}</select></label><button class="primary" id="ministry-type-export">부처별 비교표 엑셀 ↓</button><a class="button" href="#types">권역별 비교 →</a><span id="ministry-type-status" role="status"></span></div><section class="card cross-comparison"><h2>중복 제거 합계와 부처별 반복 합계</h2><p class="cross-help">추가 반복분은 실제 중복 재원이나 추가 예산이 아닙니다. 아래 여섯 행은 서로 겹치는 기준이므로 합산하지 않습니다. 복수 부처 기재 사업은 서로 다른 표기가 2개 이상인 사업입니다.</p><div id="ministry-type-totals"></div></section><section class="card cross-comparison"><h2>자료 기재 부처 ${d.table.length}개 표기별 비교</h2><p class="cross-help">각 칸을 누르면 해당 부처·사업구분의 사업 목록으로 이동합니다. 금액 단위: 억원. 보류·미확인은 금액 합계에서 제외하고 건수로 표시합니다. —는 금액 미확인이며 0이 아닙니다.</p><div id="ministry-type-table"></div></section>`;
 function table(rows,clickable){const key=document.querySelector('#ministry-type-metric').value,i=Math.max(0,CROSS_METRICS.findIndex(m=>m[0]===key)-1);return `<div class="table-wrap"><table class="cross-table ministry-type-table"><thead><tr><th scope="col">${clickable?'자료 기재 부처':'집계 기준'}</th>${[...TYPE_GROUPS,'합계'].map(t=>`<th scope="col">${E(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${E(r.name)}</th>${r.cells.map(c=>{const b=c.rows[i],q=new URLSearchParams({ministry:r.name,source:'all'});if(c.name!=='합계')q.set('type',c.name);if(key!=='count')q.set('budget',key);const body=`<strong>${key==='count'?N(b[1])+(r.name.includes('반복')?'회':'건'):b[3]===null?'—':N(b[3])}</strong>${key==='count'?'':`<small>사업 ${N(b[1])} · 금액 포함 ${N(b[4])}</small><small>잠정 집계 ${N(b[5])}</small><small class="cross-pending">보류 ${N(b[6])} · 미확인 ${N(b[7])}</small>`}`;return `<td>${clickable?`<a href="#projects?${E(q.toString())}" aria-label="${E(r.name+' '+c.name+' 사업 보기')}">${body}</a>`:body}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
 function draw(){document.querySelector('#ministry-type-totals').innerHTML=table(d.totals,false);document.querySelector('#ministry-type-table').innerHTML=table(d.table,true)}document.querySelector('#ministry-type-metric').onchange=draw;draw();
 document.querySelector('#ministry-type-export').onclick=()=>{const b=document.querySelector('#ministry-type-export'),s=document.querySelector('#ministry-type-status');b.disabled=true;try{const blob=window.AtlasXlsx.workbook(ministryTypeSheets(D.projects,ministryRows)),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='부처별_사업구분_비교표_'+new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})+'.xlsx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);s.textContent='비교표·중복집계 구분·복수부처 사업·부처 원문과 출처의 다운로드를 시작했습니다.'}catch(e){s.textContent='엑셀을 만들지 못했습니다. 다시 시도해 주세요.';console.error(e)}finally{b.disabled=false}};
}

function typeOverview(params){
 main.innerHTML=heading('사업구분별 현황','경제권·생활권·행재정권과 교통 사업의 사업 수·예산을 구분해서 조회합니다.')+`<div class="notice">교통으로 집계한 사업은 경제권·생활권·행재정권에서 제외합니다. 네 구분의 합계는 전체와 일치합니다. ‘행재정권’은 원자료의 ‘행재정’을 표시한 이름입니다. 금액은 보류·미확인을 제외한 부분합입니다.</div>${regionTypePanel()}<h2 class="type-subtitle">권역별 상세 현황</h2><div class="card type-controls"><label>권역<select id="type-region"><option value="">전체 권역</option>${D.regions.map(r=>`<option value="${E(r.region)}" ${params.get('region')===r.region?'selected':''}>${E(r.region)}</option>`).join('')}</select></label><a class="button" id="type-search-link" href="#projects">상세 조건 검색 →</a><button class="primary" id="type-export">현재 범위 엑셀 ↓</button><span data-search-export-status role="status"></span></div><section class="card selection-summary" id="type-totals"></section><details class="card type-detail"><summary>교통 분류 기준과 금액 집계 방식</summary><p>${E(TYPE_SCOPE)}</p><p>${E(TYPE_BUDGET_NOTE)}</p><p>요약서의 사업명·사업 내용을 기준으로 서비스의 집계 구분을 정했습니다. 원자료의 공식 분류 변경이나 소관 확정을 뜻하지 않습니다. 사업별 출처와 내용은 엑셀의 사업구분내역 및 사업 상세에서 확인할 수 있습니다.</p></details><details class="card type-detail"><summary>복합사업·제도 사업 등 원자료 구분을 유지한 주요 항목</summary><div id="type-retained"></div></details>`;
 let ps=[];function draw(){const region=document.querySelector('#type-region').value;ps=D.projects.filter(p=>!region||p.region===region);const q=new URLSearchParams(region?{region}:{});document.querySelector('#type-totals').innerHTML=typeSummaryTable(ps,q);document.querySelector('#type-search-link').href='#projects?'+q;document.querySelector('#type-retained').innerHTML=ps.filter(p=>TYPE_RETAIN_NOTES[p.id]).map(p=>`<article class="type-retained"><h3><a href="${link(p)}">${E(p.title)}</a></h3><small>${E(p.id)} · ${E(projectType(p))}</small><p>${E(projectTypeReason(p))}</p>${meta(p.summary_source,p.summary_location)}</article>`).join('')||'<p>이 권역에 별도 표시할 항목이 없습니다.</p>'}
 document.querySelector('#type-region').onchange=draw;
 document.querySelector('#type-export').onclick=()=>exportSelection({kind:'search',name:'사업구분별 현황',ids:ps.map(p=>p.id),criteria:[['권역',document.querySelector('#type-region').value||'전체'],['집계 구분','경제권·생활권·행재정권·교통 (상호 중복 없음)'],['교통 범위',TYPE_SCOPE]]});draw();bindRegionTypePanel();
}

function searchValues(value){return [...new Set((Array.isArray(value)?value:[value]).filter(Boolean))]}
function searchProjectRows(projects,records,v){
 const fields=['whole','window','national'],metric=fields.includes(v.budget)?v.budget:'whole';
 const min=v.min?.trim()?Number(v.min):null,max=v.max?.trim()?Number(v.max):null;
 if((min!==null&&(!Number.isFinite(min)||min<0))||(max!==null&&(!Number.isFinite(max)||max<0))||(min!==null&&max!==null&&min>max))return {rows:[],error:'최소 금액과 최대 금액을 확인해 주세요. 최소 금액은 최대 금액보다 클 수 없습니다.'};
 const regions=searchValues(v.region),chosenMinistries=searchValues(v.ministry);
 const ministries=new Set(records.filter(r=>chosenMinistries.includes(r.label)&&(!v.source||v.source==='all'||r.origin===v.source)).map(r=>r.id));
 const words=(v.q||'').trim().toLowerCase().split(/\s+/).filter(Boolean);
 const known=(p,k)=>typeof p[k]==='number'&&Number.isFinite(p[k])&&!String(p[k+'_status']||'').includes('보류');
 const rows=projects.filter(p=>{
  if(regions.length&&!regions.includes(p.region))return false;
  if(chosenMinistries.length&&!ministries.has(p.id))return false;
  if(searchValues(v.type).length&&!searchValues(v.type).includes(projectType(p)))return false;
  if(v.category&&p.category!==v.category)return false;
  if(v.term&&!(p.terms||[]).some(t=>t.trim()===v.term))return false;
  if(!words.every(w=>[p.title,p.id,p.search_text,p.summary_body,p.summary_ministry,p.detail_ministry].join(' ').toLowerCase().includes(w)))return false;
  if(v.missing==='yes'&&fields.every(k=>known(p,k)))return false;
  if(v.missing==='no'&&!fields.every(k=>known(p,k)))return false;
  const held=String(p[metric+'_status']||'').includes('보류');
  if(v.status==='known'&&!known(p,metric))return false;
  if(v.status==='held'&&!held)return false;
  if(v.status==='unknown'&&(held||known(p,metric)))return false;
  if((min!==null||max!==null)&&(!known(p,metric)||(min!==null&&p[metric]<min)||(max!==null&&p[metric]>max)))return false;
  return true;
 });
 if(v.sort==='title')rows.sort((a,b)=>a.title.localeCompare(b.title,'ko'));
 else if(fields.includes(v.sort))rows.sort((a,b)=>{const x=known(a,v.sort)?a[v.sort]:null,y=known(b,v.sort)?b[v.sort]:null;return x===null?(y===null?0:1):y===null?-1:y-x});
 return {rows,error:''};
}
function projectSearchCriteria(v){
 return [['검색어',v.q||'전체'],['권역',searchValues(v.region).join(' · ')||'전체'],['부처 (자료 기재 기준)',searchValues(v.ministry).join(' · ')||'전체'],['복수 선택 적용 방식','권역 내 또는 부처 내에서는 하나라도 해당하면 포함하고, 권역·부처·그 밖의 조건은 함께 적용합니다. 사업번호 중복은 제거합니다.'],['부처 기재 자료',v.source==='summary'?'요약서':v.source==='detail'?'상세서':'요약서·상세서'],['사업구분 (교통 별도)',searchValues(v.type).join(' · ')||'전체'],['원자료 사업구분',v.category||'전체'],['분야 키워드',v.term||'전체'],['예산 항목',({whole:'전체 사업비',window:'2027~2032년 투자액',national:'해당 기간 국비 요구액'})[v.budget]||'전체 사업비'],['최소 금액 (억원)',v.min||'제한 없음'],['최대 금액 (억원)',v.max||'제한 없음'],['금액 확인 상태',({known:'금액 확인',held:'보류',unknown:'기타 미확인'})[v.status]||'전체'],['미확인 금액 포함 여부',v.missing==='yes'?'미확인 금액 있는 사업':v.missing==='no'?'세 가지 금액 모두 확인':'전체'],['정렬',({original:'자료 순서',title:'사업명 순',whole:'전체 사업비 큰 순',window:'기간 투자액 큰 순',national:'국비 요구액 큰 순'})[v.sort]||'자료 순서']];
}
function projects(params){
 const ministries=[...new Set(ministryRows.map(r=>r.label))].sort((a,b)=>a.localeCompare(b,'ko'));
 const options=(values,empty)=>`<option value="">${empty}</option>`+values.map(v=>`<option value="${E(v)}">${E(v)}</option>`).join('');
 const choices=(name,title,values)=>`<fieldset class="multi-search-field"><legend>${title}</legend><details class="multi-search-picker"><summary><span data-choice-summary="${name}">전체</span><small>여러 개 선택</small></summary><div class="multi-search-body">${name==='ministry'?'<input type="search" data-choice-search="ministry" aria-label="부처 목록에서 찾기" placeholder="부처 이름 찾기">':''}<button type="button" data-choice-clear="${name}">전체로 초기화</button><div class="multi-search-options">${values.map(value=>`<label data-choice-option="${name}"><input type="checkbox" name="${name}" value="${E(value)}">${E(value)}</label>`).join('')}</div><p data-choice-empty="${name}" hidden>일치하는 부처가 없습니다.</p></div></details><p class="multi-search-selected" data-choice-selected="${name}">선택하지 않으면 전체를 검색합니다.</p></fieldset>`;
 main.innerHTML=heading('사업 검색·다운로드','권역·부처·분야·예산 조건을 조합해 사업을 검색하고, 검색 결과 전체를 엑셀로 내려받을 수 있습니다.')+`<form id="search-form" class="advanced-search"><div class="filters"><label>검색어<input name="q" type="search" placeholder="사업명, 사업번호, 내용 검색"></label>${choices('region','권역',D.regions.map(r=>r.region))}${choices('ministry','부처 (자료 기재 기준)',ministries)}<label>부처 기재 자료<select name="source"><option value="all">요약서·상세서</option><option value="summary">요약서</option><option value="detail">상세서</option></select></label>${choices('type','사업구분 (교통 별도)',TYPE_GROUPS)}<label>원자료 사업구분<select name="category">${options([...new Set(D.projects.map(p=>p.category))],'전체 구분')}</select></label><label>분야 키워드<select name="term">${options(D.terms,'전체 분야')}</select></label></div><div class="search-budget-fields"><label>예산 항목<select name="budget"><option value="whole">전체 사업비</option><option value="window">2027~2032년 투자액</option><option value="national">해당 기간 국비 요구액</option></select></label><label>최소 금액 (억원)<input name="min" type="number" min="0" step="any" placeholder="제한 없음"></label><label>최대 금액 (억원)<input name="max" type="number" min="0" step="any" placeholder="제한 없음"></label><label>금액 확인 상태<select name="status"><option value="">전체</option><option value="known">금액 확인</option><option value="held">보류</option><option value="unknown">기타 미확인</option></select></label></div><p class="search-help">권역·부처·사업구분은 여러 개 선택할 수 있습니다. 선택한 권역 중 하나, 선택한 부처 중 하나에 해당하는 사업을 찾고 다른 조건도 함께 적용합니다. 선택하지 않은 항목은 전체로 검색합니다. 같은 사업은 한 번만 표시합니다. 검색어를 띄어 쓰면 입력한 단어가 모두 포함된 사업을 찾습니다. 금액 범위와 확인 상태는 선택한 예산 항목에 적용합니다. 금액 범위 지정 시 보류·미확인 사업은 제외됩니다. 부처는 자료에 적힌 명칭을 사용하며 약칭과 정식 명칭을 구분합니다.</p><div class="filter-extra"><label>정렬<select name="sort"><option value="original">자료 순서</option><option value="whole">전체 사업비 큰 순</option><option value="window">기간 투자액 큰 순</option><option value="national">국비 요구액 큰 순</option><option value="title">사업명 순</option></select></label><label>미확인 금액 포함 여부<select name="missing"><option value="">전체</option><option value="yes">미확인 금액 있는 사업</option><option value="no">세 가지 금액 모두 확인</option></select></label><span class="spacer"></span><button type="reset">조건 초기화</button><button class="primary" type="submit">검색</button></div></form><div class="search-export card"><div><strong>검색 결과 <span id="search-result-count">0</span>건</strong><p>모든 페이지의 검색 결과를 한 번에 받습니다. 사업별 자료·권역별·부처별·사업구분별 요약·검색 조건이 포함됩니다.</p></div><button class="primary" id="export-search" data-export-search disabled>검색 결과 전체 엑셀 ↓</button><span data-search-export-status role="status"></span></div><div id="search-validation" role="alert"></div><div id="results"></div>`;
 const f=document.querySelector('#search-form');for(const [name,value] of params)if(!['region','ministry','type'].includes(name)&&f.elements.namedItem(name))f.elements.namedItem(name).value=value;for(const name of ['region','ministry','type'])f.querySelectorAll(`input[name="${name}"]`).forEach(el=>el.checked=params.getAll(name).includes(el.value));
 let page=1,currentRows=[],currentCriteria=[];
 function draw(){
  const data=new FormData(f),v={...Object.fromEntries(data),region:data.getAll('region'),ministry:data.getAll('ministry'),type:data.getAll('type')},result=searchProjectRows(D.projects,ministryRows,v);currentRows=result.rows;currentCriteria=projectSearchCriteria(v);
  for(const name of ['region','ministry','type']){const chosen=v[name];document.querySelector(`[data-choice-summary="${name}"]`).textContent=chosen.length?`${chosen.length}개 선택`:({region:'전체 권역',ministry:'전체 부처',type:'전체 구분'})[name];document.querySelector(`[data-choice-selected="${name}"]`).textContent=chosen.length?chosen.join(' · '):'선택하지 않으면 전체를 검색합니다.'}
  window.ACTIVE_SELECTION_RESULTS=currentRows.map(p=>p.id);
  document.querySelector('#search-validation').textContent=result.error;
  document.querySelector('#search-result-count').textContent=N(currentRows.length);
  document.querySelector('#export-search').disabled=exportBusy||!currentRows.length;
  const query=new URLSearchParams();for(const [key,value] of Object.entries(v))for(const item of (Array.isArray(value)?value:[value]))if(item)query.append(key,item);history.replaceState(null,'','#projects?'+query.toString());
  const pages=Math.max(1,Math.ceil(currentRows.length/20));page=Math.min(page,pages);
  document.querySelector('#results').innerHTML=currentRows.length?`<div class="result-heading"><h2>사업 목록</h2><small>${(page-1)*20+1}–${Math.min(page*20,currentRows.length)} / ${N(currentRows.length)}건</small></div><div class="card table-wrap"><table class="results-table"><thead><tr><th>사업</th><th>자료 기재 부처</th><th>전체 사업비</th><th>기간 투자액</th><th>국비 요구액</th><th>관련 자료</th></tr></thead><tbody>${currentRows.slice((page-1)*20,page*20).map(p=>`<tr><td class="project-title"><a href="${link(p)}"><span class="id">${E(p.id)} · ${E(projectType(p))} (원자료: ${E(p.category)})</span><strong>${E(p.title)}</strong></a><div class="source-meta">관련 자료 ${p.source_count}건 · ${E(p.public_status)}</div></td><td><small>요약서</small><br>${E(p.summary_ministry||'미기재')}<br><small>상세서</small><br>${E(p.detail_ministry||'미기재')}</td>${['whole','window','national'].map(k=>`<td class="num">${N(p[k])}<span class="count-note">${E(budgetStatusLabel(p[k+'_status']))}</span></td>`).join('')}<td><a class="button" href="${link(p,'graph')}">자료 보기</a></td></tr>`).join('')}</tbody></table></div><div class="pagination"><button id="prev" ${page===1?'disabled':''}>← 이전</button><span>${page} / ${pages}</span><button id="next" ${page===pages?'disabled':''}>다음 →</button></div>`:'<div class="empty"><h3>검색 결과가 없습니다.</h3>검색어 또는 조건을 조정해 주세요.</div>';
  document.querySelector('#prev')?.addEventListener('click',()=>{page--;draw()});document.querySelector('#next')?.addEventListener('click',()=>{page++;draw()});
 }
 f.onsubmit=e=>{e.preventDefault();page=1;draw()};const filterOptions=()=>{const q=f.querySelector('[data-choice-search]').value.trim().toLowerCase();let count=0;f.querySelectorAll('[data-choice-option="ministry"]').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(q);if(!el.hidden)count++});f.querySelector('[data-choice-empty="ministry"]').hidden=count>0};
 f.onchange=f.oninput=e=>{if(e.target.hasAttribute('data-choice-search')){filterOptions();return}page=1;draw()};f.onreset=()=>setTimeout(()=>{filterOptions();page=1;draw()},0);
 f.addEventListener('click',e=>{const b=e.target.closest('[data-choice-clear]');if(!b)return;f.querySelectorAll(`input[name="${b.dataset.choiceClear}"]`).forEach(el=>el.checked=false);page=1;draw()});
 document.querySelector('#export-search').onclick=()=>{draw();if(currentRows.length)exportSelection({kind:'search',name:'검색 결과',ids:currentRows.map(p=>p.id),criteria:currentCriteria.map(r=>[...r])})};draw();
}

async function detail(p,token){const d=await packet(p.id);if(token!==serial)return;main.innerHTML=`<div class="project-visual-strip"><img src="assets/region-${D.regions.findIndex(r=>r.region===p.region)}.svg" alt=""><span>REGIONAL PROJECT</span><small>개념 일러스트</small></div><div class="project-head"><a class="subtle" href="#projects">← 전체 사업</a><div class="id">${E(p.id)} · ${E(p.category)}</div><h1>${E(p.title)}</h1>${projectConnections(p)}<div class="tags">${pill('원문 기재')}${pill(p.detail_match||'상세 연결 미확인','neutral')}${p.terms.map(t=>`<span class="tag">${E(t)}</span>`).join('')}</div></div>${budgets(p)}${typeDetail(p)}<div class="notice">금액·부처·사업 내용은 원자료의 기재값입니다. 실제 소관 확정, 예산 승인, 집행 여부는 별도 확인되지 않았습니다.</div><div class="detail-grid"><div class="card"><h3>요약서 사업 내용</h3>${quote(p.summary_body)}${meta(p.summary_source,p.summary_location)}</div><div class="card"><h3>원문 표기</h3><dl>${[['요약서 부처',p.summary_ministry],['상세서 부처',p.detail_ministry],['기간',p.period],['상세서 기간',p.detail_period],['수행 주체 기재',d.components.owner],['입지 기재',d.components.place]].map(([k,v])=>`<dt>${k}</dt><dd>${E(v||'미확인')}</dd>`).join('')}</dl><div class="actions"><a class="button primary" href="${link(p,'graph')}">연결된 사업 연관정보 →</a></div></div></div><div class="tabs" role="tablist">${[['evidence','사업 자료 '+d.evidence.length],['public','공개자료 '+d.sources.length],['checks','자료 대조·연도별 금액'],['similar','유사 사업 비교 '+d.similar.length]].map(([k,t])=>`<button role="tab" data-tab="${k}">${t}</button>`).join('')}</div><div id="detail-content"></div>`;function tab(k){document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===k);b.setAttribute('aria-selected',b.dataset.tab===k)});let box=document.querySelector('#detail-content');if(k==='evidence'){box.innerHTML=`<div class="evidence-controls"><label>원문 항목 검색<input id="ev-search" type="search" placeholder="항목명, 자료번호, 원문 내용"></label></div><div id="ev-list"></div>`;const draw=()=>{let q=document.querySelector('#ev-search').value.toLowerCase(),es=d.evidence.filter(e=>(e.field+' '+e.evidence_id+' '+e.excerpt).toLowerCase().includes(q));document.querySelector('#ev-list').innerHTML=es.map(evidence).join('')||'<div class="empty">일치하는 자료가 없습니다.</div>'};document.querySelector('#ev-search').oninput=draw;draw()}else if(k==='public'){box.innerHTML=`<div class="notice">${E(p.public_status)}. 검색 발췌와 직접 열람 범위는 자료별로 표시합니다. 관련 문서의 존재가 동일사업·동일재원을 뜻하지 않습니다.</div><details class="card"><summary>검색 범위와 확인 기록</summary>${record(d.search)}</details>`+d.sources.map(s=>publicCard(s,d.public.find(x=>x.source_id===s.source_id)?.relation)).join('');if(!d.sources.length)box.innerHTML+='<div class="empty">설정한 검색 기준 내 연결 자료 미확인</div>'}else if(k==='checks'){box.innerHTML=`<div class="card"><h3>원자료 간 대조 기록</h3>${record(d.checks)}</div><div class="section-head"><h2>연도별 금액 원문</h2></div><div class="notice">연도 행의 일부 합계를 사업 전체 예산으로 해석하지 않습니다. 단위·기간·공란·대시 처리 기록을 함께 확인하세요.</div>`+d.annual.map(a=>`<article class="evidence-card"><h3>${E(a.year_label)} · 원문 단위: ${E(a.unit)}</h3><p class="subtle">아래 환산 금액: 억원 · 원문 행은 원래 단위 유지</p><div class="table-wrap"><table><tr><th>국비</th><th>지방비</th><th>민자</th><th>합계</th></tr><tr>${['national','local','private','total'].map(k=>`<td>${N(a[k])}</td>`).join('')}</tr></table></div>${quote(a.raw_cells)}${meta(a.source,a.location)}<p>${E(a.row_state)} · ${E(a.unknown_reason)} ${E(a.limit)}</p></article>`).join('')}else box.innerHTML=`<div class="notice">문구 유사도와 공통 키워드에 따른 대조입니다. 동일사업·사업 중복·재원 중복 관계는 미확인입니다.</div>`+d.similar.map(s=>{let other=P.get(s.id_a===p.id?s.id_b:s.id_a);return `<article class="compare-card card"><h3><a href="${link(other)}">${E(other.title)} ↗</a></h3><p>${E(other.id)} · 문구 유사도 ${E(s.cosine)}</p><p>공통 키워드: ${E(s.shared_terms)}</p><div class="source-meta">${E(s.source_a)}<br>${E(s.source_b)}</div>${pill('문구 비교','rule')} <a class="button" href="${link(other)}">상대 사업 원문 보기</a></article>`}).join('')}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));tab('evidence')}
const labels={id:'사업번호',region:'권역',title:'사업명',summary_title:'요약서 사업명',detail_title:'상세서 사업명',title_comparison:'사업명 대조',period_comparison:'기간 대조',ministry_comparison:'부처 표기 대조',total_comparison:'총액 대조',query:'검색식',searched:'검색일',status:'확인 상태',method:'방법',limit:'확인 범위',source_ids:'연결 출처 ID',error:'검색 오류',selected_reference_count:'선정 참고자료 수',returned_primary_domain_count:'공식 도메인 검색 결과 수'};
Object.assign(labels,{detail_match:'상세서 연결 방식',summary_period:'요약서 기간',detail_period:'상세서 기간',summary_total:'요약서 총액 (억원)',detail_total:'상세서 총액 (억원)',total_delta:'총액 차이 (억원)',total_difference_band:'총액 차이 구간',summary_ministry:'요약서 부처',detail_ministry:'상세서 부처',ministry_source:'부처 기재 출처',placeholder_lines:'임시 표기 행 수',placeholder_source:'임시 표기 출처',summary_location:'요약서 위치',detail_location:'상세서 위치',known_whole:'전체 사업비 숫자 있음 (1/0)',known_window:'기간 투자액 숫자 있음 (1/0)',known_national:'기간 국비 숫자 있음 (1/0)',annual_rows:'연도 행 수',annual_valid_rows:'대조 가능 연도 행 수',annual_years:'기재 연도',annual_partial_total:'확인 연도 부분합 (억원)',annual_partial_national:'확인 연도 국비 부분합 (억원)',annual_national_rows:'국비 기재 연도 행 수',annual_invalid_rows:'대조 제한 연도 행 수',annual_arithmetic_difference_rows:'산술차이 연도 행 수',annual_source:'연도별 투자계획 출처',annual_limitation:'연도표 확인 범위',tag:'검출 용어',pattern:'검출 규칙',meaning:'의미',scope:'범위'});
Object.assign(labels,{detail_match:'상세서 연결 방식',summary_period:'요약서 기간',detail_period:'상세서 기간',summary_total:'요약서 총액 (억원)',detail_total:'상세서 총액 (억원)',total_delta:'총액 차이 (억원)',total_difference_band:'총액 차이 구간',summary_ministry:'요약서 부처',detail_ministry:'상세서 부처',ministry_source:'부처 기재 출처',placeholder_lines:'임시 표기 행 수',placeholder_source:'임시 표기 출처',summary_location:'요약서 위치',detail_location:'상세서 위치',known_whole:'전체 사업비 숫자 있음 (1/0)',known_window:'기간 투자액 숫자 있음 (1/0)',known_national:'기간 국비 숫자 있음 (1/0)',annual_rows:'연도 행 수',annual_valid_rows:'대조 가능 연도 행 수',annual_years:'기재 연도',annual_partial_total:'확인 연도 부분합 (억원)',annual_partial_national:'확인 연도 국비 부분합 (억원)',annual_national_rows:'국비 기재 연도 행 수',annual_invalid_rows:'대조 제한 연도 행 수',annual_arithmetic_difference_rows:'산술차이 연도 행 수',annual_source:'연도별 투자계획 출처',annual_limitation:'연도표 확인 범위',tag:'검출 용어',pattern:'검출 규칙',meaning:'의미',scope:'범위'});
function record(obj){return `<dl>${Object.entries(obj).filter(([k,v])=>v!==null&&v!==undefined&&v!=='').map(([k,v])=>`<dt>${E(labels[k]||k)}</dt><dd>${E(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl>`}
async function graph(p,token){
 const d=await packet(p.id);if(token!==serial)return;
 const pub=d.sources.filter(s=>d.public.some(c=>c.source_id===s.source_id));
 const groups=[
  {key:'original',title:'사업 자료',count:d.evidence.length,level:'original',description:'사업내용 · 예산 · 기간 · 추진 주체'},
  {key:'public',title:'공개자료',count:pub.length,level:'public',description:'공개 문서와 열람 범위'},
  {key:'record',title:'권역·부처 표기',count:1+p.ministry_terms.length,level:'original',description:'요약서에 기재된 정보'},
  {key:'terms',title:'분야 키워드',count:p.terms.length,level:'rule',description:'사업 내용의 키워드 분류'},
  {key:'similar',title:'내용 유사 사업',count:d.similar.length,level:'rule',description:'유사 문구를 가진 사업 연결'}
 ];
 main.innerHTML=heading('사업 연관정보','사업을 선택하고, 아래의 자료 유형을 눌러 확인하세요. 원문과 공개자료를 종류별로 정리했습니다.')+`<form id="graph-search" class="graph-controls"><label>사업 찾기<input id="graph-query" list="project-options" placeholder="사업번호 또는 사업명" value="${E(p.id)}"><datalist id="project-options">${D.projects.map(x=>`<option value="${E(x.id)}">${E(x.title)}</option>`).join('')}</datalist></label><button class="primary">사업 이동</button><a class="button" href="${link(p)}">사업 상세</a></form><div id="graph-message" role="status"></div><div class="actions"><a class="button" href="#explore">권역·부처에서 연결 사업 찾기 →</a></div>${projectConnections(p)}<div class="atlas-toolbar">${levelLegend()}<button id="large-labels" aria-pressed="false">글씨 더 크게</button></div><div class="evidence-atlas"><section class="relationship-map" aria-label="권역별 사업정보 연결도"><div class="map-caption">선택한 사업 <span>사업 → 자료 유형 → 원문</span></div><button class="focus-project" id="focus-project" aria-label="선택 사업의 관련 자료 전체 보기"><span class="focus-kicker">${E(p.region)} · ${E(p.category)}</span><strong>${E(p.title)}</strong><span>${E(p.id)} <b>관련 자료 전체 보기 ↓</b></span></button><div class="map-stem" aria-hidden="true"></div><div class="evidence-groups">${groups.map((g,i)=>`<button class="evidence-group ${g.level}" data-group="${g.key}" aria-controls="inspector"><span class="group-number">0${i+1}</span><span class="group-title">${g.title} <b>${g.count}</b></span><span class="group-description">${g.description}</span><span class="group-action">${g.count?'자료 보기 →':'연결 항목 없음'}</span></button>`).join('')}</div><div class="map-note">${d.evidence.length}개 사업 자료와 ${pub.length}개 공개자료를 묶어 표시했습니다. 각 묶음에서 모든 연결 항목을 확인할 수 있습니다.</div><div class="notice amber">공개자료·문구 대조 연결은 동일사업 확정을 뜻하지 않습니다.</div></section><aside class="evidence-reader" id="inspector" aria-label="선택한 사업의 관련 자료" aria-live="polite" tabindex="-1"></aside></div>`;
 document.querySelector('#graph-search').onsubmit=e=>{e.preventDefault();const q=document.querySelector('#graph-query').value.trim();let found=P.get(q)||D.projects.find(x=>x.title===q)||D.projects.find(x=>q&&(x.title+' '+x.id).includes(q));if(found){if(found.id===p.id)show('all');else location.hash=link(found,'graph')}else document.querySelector('#graph-message').textContent='일치하는 사업이 없습니다. 사업명 또는 ID를 확인해 주세요.'};
 const originalRows=()=>d.evidence.map(e=>`<details class="reader-item"><summary><span><strong>${E(e.field)}</strong><small>${E(e.evidence_id)} · ${E(e.location)}</small></span><span class="reader-plus" aria-hidden="true">＋</span></summary><div class="reader-body">${pill('원문 기재')}${quote(e.excerpt)}${meta(e.source,e.location)}</div></details>`).join('')||'<p class="reader-empty">연결된 사업 자료가 없습니다.</p>';
 const publicRows=()=>pub.map(s=>`<details class="reader-item"><summary><span><strong>${E(s.title)}</strong><small>${E(s.read_level)}</small></span><span class="reader-plus" aria-hidden="true">＋</span></summary><div class="reader-body">${publicCard(s,d.public.find(c=>c.source_id===s.source_id)?.relation)}</div></details>`).join('')||'<p class="reader-empty">설정한 검색 기준 내 연결 공개자료 미확인</p>';
 function content(k){
  if(k==='original')return `<p class="reader-help">항목을 펼치면 자료 발췌과 문서·문단 위치가 보입니다.</p>${originalRows()}`;
  if(k==='public')return `<div class="notice">${E(p.public_status)}. 자료별 열람 범위와 동일사업 미확인을 구분합니다.</div>${publicRows()}${d.sources.length>pub.length?`<p class="source-meta">기존 일반 참고자료 ${d.sources.length-pub.length}개는 <a href="${link(p)}">사업 상세의 공개자료 탭</a>에서 확인할 수 있습니다.</p>`:''}`;
  if(k==='record')return `${projectConnections(p)}${pill('원문 기재')}<dl><dt>권역</dt><dd>${E(p.region)}</dd><dt>요약서 부처 표기</dt><dd>${E(p.summary_ministry||'미기재')}</dd><dt>상세서 부처 표기</dt><dd>${E(p.detail_ministry||'미확인')}</dd></dl>${meta(p.summary_source,p.summary_location)}${meta(p.detail_source,p.detail_location)}<div class="notice amber">원문에 적힌 부처입니다. 실제 소관 확정은 미확인입니다.</div>`;
  if(k==='terms')return `<p class="reader-help">사업 내용의 키워드 분류입니다. 실제 수행 여부·독립 내역사업 여부는 미확인입니다.</p><div class="tags">${p.terms.map(t=>`<span class="tag">${E(t)}</span>`).join('')||'해당 키워드 없음'}</div><h3 class="reader-subtitle">용어 대조에 사용한 원문</h3>${d.evidence.filter(e=>String(p.detail_content_evidence||p.summary_evidence).includes(e.evidence_id)).map(evidence).join('')}`;
  return `<div class="notice amber">문구 대조 결과입니다. 동일사업·중복재원 관계는 미확인입니다.</div>${d.similar.map(s=>{const other=P.get(s.id_a===p.id?s.id_b:s.id_a);return `<details class="reader-item"><summary><span><strong>${E(other.title)}</strong><small>${E(other.id)} · 문구 유사도 ${E(s.cosine)}</small></span><span class="reader-plus" aria-hidden="true">＋</span></summary><div class="reader-body"><p>공통 키워드: ${E(s.shared_terms)}</p>${meta(s.source_a,s.source_b)}<div class="actions"><a class="button primary" href="${link(other,'graph')}">이 사업의 관련 자료 →</a><a class="button" href="${link(other)}">사업 원문 보기</a></div></div></details>`}).join('')||'<p class="reader-empty">해당 규칙으로 연결된 내용 유사 사업이 없습니다.</p>'}`;
 }
 function show(k,focus=false){
  const box=document.querySelector('#inspector');const g=groups.find(x=>x.key===k);
  document.querySelectorAll('[data-group]').forEach(b=>{b.classList.toggle('active',b.dataset.group===k);b.setAttribute('aria-pressed',String(b.dataset.group===k))});
  document.querySelector('#focus-project').classList.toggle('active',k==='all');
  box.innerHTML=`<div class="reader-header"><span class="eyebrow">PROJECT DOCUMENTS</span>${k!=='all'?'<button class="link-button" id="reader-back">← 전체 자료</button>':''}<h2>${k==='all'?'관련 자료 한눈에 보기':g.title+' <span class="muted">'+g.count+'</span>'}</h2><p class="reader-project-title">${E(p.title)}</p></div>`+(k==='all'?`<div class="reader-totals"><button data-read="original"><b>${d.evidence.length}</b><span>사업 자료</span></button><button data-read="public"><b>${pub.length}</b><span>공개자료</span></button></div><div class="reader-status"><strong>자료 확인 현황</strong><p>${pill('원문 기재')} ${E(p.detail_match||'상세 연결 미확인')}</p><p>${pill('공개자료','public')} ${E(p.public_status)}</p><p>${pill('미확인','unknown')} 실제 소관·동일사업·재원 관계</p></div><h3 class="reader-subtitle">사업 자료 <small>${d.evidence.length}개 · 항목을 눌러 펼치기</small></h3>${originalRows()}<h3 class="reader-subtitle">공개자료 <small>${pub.length}개</small></h3>${publicRows()}<a class="button reader-detail-link" href="${link(p)}">사업의 전체 분석표 보기 →</a>`:content(k));
  box.scrollTop=0;
  document.querySelector('#reader-back')?.addEventListener('click',()=>show('all'));
  box.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>show(b.dataset.read));
  if(focus&&matchMedia('(max-width:1000px)').matches){box.scrollIntoView({behavior:'smooth',block:'start'});box.focus({preventScroll:true})}
 }
 document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>show(b.dataset.group,true));
 document.querySelector('#focus-project').onclick=()=>show('all',true);
 document.querySelector('#large-labels').onclick=e=>{const on=document.querySelector('.evidence-atlas').classList.toggle('larger-type');e.currentTarget.setAttribute('aria-pressed',on);e.currentTarget.textContent=on?'기본 글씨 크기':'글씨 더 크게'};
 show('all');
}

async function sourcePage(token){const ds=await sources();if(token!==serial)return;main.innerHTML=heading('사업·참고자료','공개 참고자료 전체를 검색합니다. 사업별 원문 문단·표 위치는 사업 상세의 ‘사업 자료’에서 확인할 수 있습니다.')+`<div class="actions"><a class="button" href="#projects">사업별 사업 자료 찾기 →</a></div><label>공개자료 검색<input type="search" id="source-q" placeholder="문서명, 출처 ID, 발행 도메인"></label><div id="source-results"></div>`;let page=1;function draw(){const q=document.querySelector('#source-q').value.toLowerCase(),rows=ds.sources.filter(s=>(s.title+' '+s.source_id+' '+s.publisher_domain).toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages);document.querySelector('#source-results').innerHTML=`<div class="result-heading"><h2>${N(rows.length)}개 자료</h2><small>기존 일반 참고자료 89개 포함</small></div>`+rows.slice((page-1)*12,page*12).map(s=>publicCard(s)+`<div class="tags">${(ds.refs[s.source_id]||[]).map(id=>`<a class="tag" href="${link(P.get(id))}">${E(id)} ↗</a>`).join('')}</div>`).join('')+`<div class="pagination"><button id="sprev" ${page===1?'disabled':''}>이전</button>${page} / ${pages}<button id="snext" ${page===pages?'disabled':''}>다음</button></div>`;document.querySelector('#sprev').onclick=()=>{page--;draw()};document.querySelector('#snext').onclick=()=>{page++;draw()}}document.querySelector('#source-q').oninput=()=>{page=1;draw()};draw()}
function method(){main.innerHTML=heading('자료 확인 현황·집계 기준','데이터에 있는 사실, 대조 규칙으로 얻은 연결, 확인하지 못한 관계를 구분합니다.')+`<div class="card">${levelLegend()}<dl><dt>원문 기재</dt><dd>요약서·상세서에 적힌 내용과 문서·문단·표 위치입니다. 계획의 승인·집행을 확인한 것은 아닙니다.</dd><dt>공개자료</dt><dd>공개 문서에서 확인된 제목·검색 발췌·직접 열람 범위입니다. 대부분 검색 발췌 수준이며 자료별 열람 수준을 표시합니다.</dd><dt>문구 비교</dt><dd>정의어 검출과 문구 유사도에 따른 연결입니다. 동일사업·독립 내역사업·중복재원 관계를 확정하지 않습니다.</dd><dt>미확인</dt><dd>누락·연결 제한·보류·검증되지 않은 관계입니다. 미확인을 0 또는 ‘없음’으로 바꾸지 않습니다.</dd></dl></div><div class="section-head"><h2>분석 범위</h2></div><div class="card"><p>전체 1,312건, 사업 자료 19,731개, 연도 행 6,507개, 공개자료 1,773개를 수록합니다. 상세서 연결이 없는 19건과 제목만 연결된 8건은 원래 확인 상태를 유지합니다.</p><p>사업명 문자열 확인 31건, 관련어 문서 확인 800건, 설정한 검색·대조 기준 내 미확인 481건입니다. 앞의 두 분류도 동일사업 여부는 미확인입니다.</p><p>유사 사업 비교는 전체 860,016쌍에서 권역 내·권역 간 사업별 상위 3개, 유사도 0.15 이상을 합친 1,934쌍입니다. 그래프에서 선택적으로 표시합니다.</p><p>부처는 원문 표기를 유지합니다. 부처 변경 의견·전문가 판단·정책 제안은 이 열람 데이터에 포함하지 않았습니다.</p></div><div class="section-head"><h2>분야 키워드 검출 규칙</h2></div>${D.rules.map(r=>`<details class="card"><summary>${E(r.tag)}</summary>${record(r)}</details>`).join('')}`}
function downloads(){main.innerHTML=heading('자료 내려받기','동일한 데이터로 분석표와 연결 관계를 확인할 수 있습니다.')+`<div class="download-grid">${[['project-analysis.xlsx','전체 분석 엑셀','사업 목록, 관련 자료, 비교표, 검색 기록과 확인 현황'],['project-catalog.json','사업 목록 데이터','전체 1,312개 사업의 기재 정보'],['knowledge-graph.json','사업 연관정보 데이터',N(D.meta.graphNodes)+'개 노드 · '+N(D.meta.graphEdges)+'개 연결 · 출처와 자료 확인 현황']].map(([f,t,s])=>`<a class="download-card card" href="downloads/${f}" download><div class="download-icon">↓</div><h2>${t}</h2><p>${s}</p><span class="pill neutral">${f.split('.').pop().toUpperCase()}</span></a>`).join('')}</div><div class="notice">2026.10.30 기준 자료입니다. 이후 변경된 사업·기관·예산 정보는 자동 반영되지 않습니다.</div>`}
const ministryRows=window.MINISTRY_INDEX;
const hubLink=(kind,name='',source='all')=>'#explore?'+new URLSearchParams({kind,name,source}).toString();
function projectConnections(p){const rows=ministryRows.filter(r=>r.id===p.id);return `<div class="connection-chips"><a href="${hubLink('region',p.region)}">${E(p.region)} · 연결 사업 ↗</a>${[...new Set(rows.map(r=>r.label))].map(label=>`<a href="${hubLink('ministry',label)}">${E(label)} <small>${[...new Set(rows.filter(r=>r.label===label).map(r=>r.origin==='summary'?'요약서':'상세서'))].join('·')}</small> ↗</a>`).join('')}</div>`}
function explore(params){
 const kind=params.get('kind')==='ministry'?'ministry':'region',name=params.get('name')||'',source=['summary','detail'].includes(params.get('source'))?params.get('source'):'all';
 const entries=ministryRows.filter(r=>source==='all'||r.origin===source),names=kind==='region'?D.regions.map(r=>r.region):[...new Set(entries.map(r=>r.label))].sort((a,b)=>a.localeCompare(b,'ko'));
 const ids=kind==='region'?new Set(D.projects.filter(p=>!name||p.region===name).map(p=>p.id)):new Set(entries.filter(r=>!name||r.label===name).map(r=>r.id));
 const connected=D.projects.filter(p=>ids.has(p.id));
 main.innerHTML=heading('권역·부처별 연결 사업','권역이나 원문에 기재된 부처를 선택하고, 사업 카드를 눌러 연결된 사업 자료를 확인하세요.')+`<div class="actions"><a class="button" href="#compare?kind=${kind}">사업 수·예산 비교 →</a><a class="button" href="#multiple">복수 부처 기재 사업 보기 →</a></div><div class="hub-switch"><a class="button ${kind==='region'?'primary':''}" href="${hubLink('region')}">권역으로 보기</a><a class="button ${kind==='ministry'?'primary':''}" href="${hubLink('ministry')}">자료 기재 부처로 보기</a></div><div class="notice">부처는 요약서·상세서의 부처 항목에서 이름이 직접 확인된 경우만 연결합니다. 약칭과 정식 명칭을 합치거나 실제 소관을 추정하지 않습니다. 같은 사업이 여러 부처에 연결될 수 있습니다.</div>${kind==='ministry'?`<label class="hub-source">기재 문서<select id="hub-source"><option value="all" ${source==='all'?'selected':''}>요약서 또는 상세서</option><option value="summary" ${source==='summary'?'selected':''}>요약서 기재만</option><option value="detail" ${source==='detail'?'selected':''}>상세서 기재만</option></select></label>`:''}<div class="hub-layout"><aside class="hub-picker"><h2>${kind==='region'?'권역':'자료 기재 부처'}</h2><label>목록에서 찾기<input id="hub-name-query" type="search" placeholder="${kind==='region'?'권역':'부처 표기'} 검색"></label><div id="hub-names">${names.map(n=>{const count=kind==='region'?D.regions.find(r=>r.region===n).count:new Set(entries.filter(r=>r.label===n).map(r=>r.id)).size;return `<a data-hub-name="${E(n)}" class="${name===n?'active':''}" href="${hubLink(kind,n,source)}"><span>${E(n)}</span><b>${N(count)}</b></a>`}).join('')}</div><p id="hub-name-empty" hidden>일치하는 표기가 없습니다.</p></aside><section class="hub-projects"><div class="hub-selected"><span class="eyebrow">${kind==='region'?'REGION':'ORIGINAL MINISTRY RECORD'}</span><h2>${E(name||(kind==='region'?'전체 권역':'자료 기재 부처 기재 사업'))} <span>${N(connected.length)}개 사업</span></h2><p>${name?'선택 항목 → 연결 사업 → 사업 자료':'왼쪽 목록에서 권역이나 부처를 선택하세요.'}</p></div><div class="hub-project-controls"><label>연결 사업 검색<input id="hub-project-query" type="search" placeholder="사업명 또는 사업번호"></label><label>권역<select id="hub-region"><option value="">전체 권역</option>${D.regions.filter(r=>connected.some(p=>p.region===r.region)).map(r=>`<option>${E(r.region)}</option>`).join('')}</select></label></div><div id="hub-results"></div></section></div>`;
 document.querySelector('#hub-source')?.addEventListener('change',e=>location.hash=hubLink(kind,name,e.target.value));
 document.querySelector('#hub-name-query').oninput=e=>{let visible=0;document.querySelectorAll('[data-hub-name]').forEach(el=>{el.hidden=!el.dataset.hubName.includes(e.target.value.trim());if(!el.hidden)visible++});document.querySelector('#hub-name-empty').hidden=visible>0};
 let page=1;
 function draw(){const q=document.querySelector('#hub-project-query').value.trim().toLowerCase(),reg=document.querySelector('#hub-region').value,rows=connected.filter(p=>(!reg||p.region===reg)&&(!q||(p.title+' '+p.id).toLowerCase().includes(q))),pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages);
 document.querySelector('#hub-results').innerHTML=`<div class="result-heading"><strong>${N(rows.length)}개 사업</strong><small>사업을 누르면 사업 자료로 이동</small></div><div class="hub-card-grid">${rows.slice((page-1)*12,page*12).map(p=>{const origins=kind==='ministry'?entries.filter(r=>r.id===p.id&&(!name||r.label===name)):[];return `<a class="hub-project-card" href="${link(p,'graph')}"><div class="hub-card-meta">${E(p.region)} · ${E(p.category)}<span>${p.source_count}개 사업 자료</span></div><h3>${E(p.title)}</h3><small>${E(p.id)}</small><div class="hub-raw"><span>요약서 부처 표기</span><p>${E(p.summary_ministry||'미기재')}</p>${kind==='ministry'?`<span>관련 자료</span>${origins.map(r=>`<p><b>${r.origin==='summary'?'요약서':'상세서'}</b> ${E(r.raw)}</p><small>${E(r.source)} · ${E(r.location)}</small>`).join('')}`:''}</div><div class="hub-card-footer"><span>${E(p.detail_match||'상세 연결 미확인')}</span><strong>사업 자료 보기 →</strong></div></a>`}).join('')}</div>${rows.length?'':'<div class="empty">조건에 맞는 연결 사업이 없습니다.</div>'}<div class="pagination"><button id="hub-prev" ${page===1?'disabled':''}>← 이전</button><span>${page} / ${pages}</span><button id="hub-next" ${page===pages?'disabled':''}>다음 →</button></div>`;
 document.querySelector('#hub-prev').onclick=()=>{page--;draw()};document.querySelector('#hub-next').onclick=()=>{page++;draw()};}
 document.querySelector('#hub-project-query').oninput=()=>{page=1;draw()};document.querySelector('#hub-region').onchange=()=>{page=1;draw()};draw();
}

const budgetFields=[['whole','전체 사업비'],['window','2027~2032년 투자액'],['national','해당 기간 국비 요구액']];
function budgetAggregate(ps,k){const a={sum:0,count:0,original:0,provisional:0,held:0,unknown:0};for(const p of ps){if(p[k+'_status']==='보류')a.held++;else if(p[k]===null||p[k]===undefined)a.unknown++;if(p[k]!==null&&p[k]!==undefined&&p[k+'_status']!=='보류'){a.sum+=p[k];a.count++;if(p[k+'_status']==='잠정채택')a.provisional++;else a.original++}}return a}
function budgetCompare(params){
 const kind=params.get('kind')==='ministry'?'ministry':'region';
 main.innerHTML=heading('사업 수·예산 비교','권역별·자료 기재 부처별로 사업 수와 세 가지 예산을 비교합니다. 금액이 없는 항목은 합계에서 제외하고 별도 표시합니다.')+`<div class="actions"><a class="button" href="#multiple">복수 부처 기재·중복 집계 보기 →</a></div><div class="hub-switch"><a class="button ${kind==='region'?'primary':''}" href="#compare?kind=region">권역별 비교</a><a class="button ${kind==='ministry'?'primary':''}" href="#compare?kind=ministry">자료 기재 부처별 비교</a></div><div class="notice">단위: 억원 · 철도 포함 전체 사업 기준. 표시 금액은 숫자가 있는 항목의 부분합이며 확정 예산이 아닙니다. ‘잠정채택’은 기존 데이터 상태를 유지한 것입니다. 보류·미확인 금액은 0으로 처리하지 않습니다.${kind==='ministry'?'<br><strong>부처 표기는 원문 기준입니다. 한 사업이 여러 부처에 연결될 수 있으므로 부처별 금액을 더하면 중복됩니다.</strong>':''}</div><div class="budget-filters"><label>${kind==='region'?'권역':'부처 표기'} 찾기<input id="compare-query" type="search" placeholder="이름 검색"></label>${kind==='ministry'?'<label>기재 문서<select id="compare-source"><option value="all">요약서 또는 상세서</option><option value="summary">요약서 기재만</option><option value="detail">상세서 기재만</option></select></label>':''}<label>비교·정렬 기준<select id="compare-metric"><option value="count">사업 수</option>${budgetFields.map(([k,t])=>`<option value="${k}">${t}</option>`).join('')}</select></label><label>정렬<select id="compare-order"><option value="desc">큰 순서</option><option value="asc">작은 순서</option></select></label></div><div id="comparison-output"></div><section id="held-detail" aria-live="polite" tabindex="-1"></section>`;
 let displayed=[];
 function draw(){const q=document.querySelector('#compare-query').value.trim(),source=document.querySelector('#compare-source')?.value||'all',metric=document.querySelector('#compare-metric').value,order=document.querySelector('#compare-order').value;
 const entries=ministryRows.filter(r=>source==='all'||r.origin===source),names=kind==='region'?D.regions.map(r=>r.region):[...new Set(entries.map(r=>r.label))];
 displayed=names.filter(n=>!q||n.includes(q)).map(name=>{const ids=kind==='region'?new Set(D.projects.filter(p=>p.region===name).map(p=>p.id)):new Set(entries.filter(r=>r.label===name).map(r=>r.id));const ps=D.projects.filter(p=>ids.has(p.id));return {name,ps,count:ps.length,...Object.fromEntries(budgetFields.map(([k])=>[k,budgetAggregate(ps,k)]))}});
 const val=r=>metric==='count'?r.count:r[metric].count?r[metric].sum:null;
 displayed.sort((a,b)=>{const x=val(a),y=val(b);if(x===null)return y===null?0:1;if(y===null)return -1;return (order==='desc'?y-x:x-y)||a.name.localeCompare(b.name,'ko')});
 const union=new Set(displayed.flatMap(r=>r.ps.map(p=>p.id))),ps=D.projects.filter(p=>union.has(p.id)),chart=displayed.slice(0,12),max=Math.max(1,...chart.map(r=>val(r)||0));
 const cell=(a,index,k)=>`<strong>${a.count?N(a.sum):'미확인'}</strong><span class="count-note">숫자 있음 ${N(a.count)}건 · 부분합</span><span class="count-note">원문이관 ${N(a.original)} · 잠정채택 ${N(a.provisional)}</span><button class="budget-held ${a.held+a.unknown?'has-missing':''}" data-held="${index}" data-field="${k}">보류 ${N(a.held)}건 · 기타 미확인 ${N(a.unknown)}건${a.held+a.unknown?' ↗':''}</button>`;
 document.querySelector('#comparison-output').innerHTML=`<div class="section-head"><h2>현재 목록에 연결된 고유 사업 <span class="muted">${N(ps.length)}건</span></h2><small>${displayed.length}개 ${kind==='region'?'권역':'부처 표기'} · 사업번호 중복 제거</small></div><div class="budgets">${budgetFields.map(([k,t])=>{const a=budgetAggregate(ps,k);return `<div class="budget-card"><div class="label">${t} · 기재 금액 부분합</div><strong>${a.count?N(a.sum):'미확인'} <span class="unit">${a.count?'억원':''}</span></strong><p class="budget-coverage">숫자 있음 ${a.count}건 / ${ps.length}건</p><span class="pill unknown">보류 ${a.held}건 · 기타 미확인 ${a.unknown}건</span></div>`}).join('')}</div><div class="card compare-chart"><div class="section-head"><h2>${metric==='count'?'사업 수':budgetFields.find(([k])=>k===metric)[1]} 비교</h2><small>${displayed.length>12?'현재 정렬 앞 12개 · 전체는 아래 표':'전체 목록'} · ${metric==='count'?'건':'억원'}</small></div>${chart.map(r=>`<a class="compare-bar" href="${hubLink(kind,r.name,source)}"><span class="compare-name">${E(r.name)}</span><span class="compare-track"><i style="width:${val(r)===null?0:Math.max(0,val(r)/max*100)}%"></i></span><strong>${val(r)===null?'미확인':N(val(r))}</strong></a>`).join('')||'<p class="empty">일치하는 항목이 없습니다.</p>'}</div><div class="section-head"><h2>사업 수·예산 상세 비교</h2><small>이름 → 사업 목록 · 보류 건수 → 해당 사업</small></div><div class="card table-wrap budget-comparison"><table><thead><tr><th>${kind==='region'?'권역':'자료 기재 부처'}</th><th class="num">사업 수</th>${budgetFields.map(([,t])=>`<th class="num">${t}<small>억원</small></th>`).join('')}</tr></thead><tbody>${displayed.map((r,i)=>`<tr><th scope="row"><a href="${hubLink(kind,r.name,source)}">${E(r.name)} ↗</a></th><td class="num">${N(r.count)}</td>${budgetFields.map(([k])=>`<td class="num">${cell(r[k],i,k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice amber">‘보류’는 해당 금액을 정하지 못해 합계에서 제외한 상태입니다. 현재 데이터의 보류 항목은 모두 집계 금액이 비어 있습니다. ‘기타 미확인’은 보류 표기 없이 금액이 비어 있는 항목이며, 보류와 중복 집계하지 않습니다. 미확인 금액의 합계 자체는 산출할 수 없습니다.</div>`;
 document.querySelector('#held-detail').innerHTML='';document.querySelectorAll('[data-held]').forEach(b=>b.onclick=()=>held(Number(b.dataset.held),b.dataset.field));
 }
 function held(i,k){const r=displayed[i],rows=r.ps.filter(p=>p[k+'_status']==='보류'||p[k]===null||p[k]===undefined),field=budgetFields.find(([key])=>key===k)[1];let page=1;function render(){const pages=Math.max(1,Math.ceil(rows.length/15));const box=document.querySelector('#held-detail');box.innerHTML=`<div class="section-head"><h2>${E(r.name)} · ${field}</h2><button id="held-close">닫기</button></div><div class="notice">보류·미확인 ${rows.length}건. 금액을 0으로 치환하지 않습니다. 사업을 선택하면 원문에 적힌 예산과 확인 범위를 볼 수 있습니다.</div><div class="card table-wrap"><table><thead><tr><th>사업</th><th>상태</th><th>집계 금액</th><th>관련 자료</th></tr></thead><tbody>${rows.slice((page-1)*15,page*15).map(p=>`<tr><td><span class="id">${E(p.id)}</span><a href="${link(p,'graph')}">${E(p.title)}</a></td><td>${pill(p[k+'_status']==='보류'?'보류':'미확인','unknown')}</td><td>미확인 · 합계 제외</td><td><a class="button" href="${link(p,'graph')}">원문 예산 보기</a></td></tr>`).join('')||'<tr><td colspan="4">보류·미확인 항목이 없습니다.</td></tr>'}</tbody></table></div><div class="pagination"><button id="held-prev" ${page===1?'disabled':''}>이전</button>${page} / ${pages}<button id="held-next" ${page===pages?'disabled':''}>다음</button></div>`;document.querySelector('#held-close').onclick=()=>box.innerHTML='';document.querySelector('#held-prev').onclick=()=>{page--;render()};document.querySelector('#held-next').onclick=()=>{page++;render()};}render();document.querySelector('#held-detail').scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#held-detail').focus({preventScroll:true})}
 document.querySelector('#compare-query').oninput=draw;['compare-source','compare-metric','compare-order'].forEach(id=>{const el=document.getElementById(id);if(el)el.onchange=draw});draw();
}

function multipleMinistryProjects(projects,records,source='all'){
 const byId=new Map();for(const r of records){if(source!=='all'&&r.origin!==source)continue;if(!byId.has(r.id))byId.set(r.id,[]);byId.get(r.id).push(r)}
 return projects.map(p=>{const rs=byId.get(p.id)||[],labels=[...new Set(rs.map(r=>r.label))],together=['summary','detail'].some(origin=>new Set(rs.filter(r=>r.origin===origin).map(r=>r.label)).size>1);return {p,records:rs,labels,m:labels.length,together}}).filter(r=>r.m>1);
}
function multipleMinistryTotals(rows){
 const out={unique:rows.length,repeated:rows.reduce((s,r)=>s+r.m,0)};out.extra=out.repeated-out.unique;
 for(const k of ['whole','window','national']){const a={unique:0,repeated:0,extra:0,known:0,held:0,unknown:0,heldRepeated:0,unknownRepeated:0,provisional:0};for(const r of rows){const p=r.p;if(p[k+'_status']==='보류'){a.held++;a.heldRepeated+=r.m}else if(p[k]===null||p[k]===undefined){a.unknown++;a.unknownRepeated+=r.m}else{a.known++;a.unique+=p[k];a.repeated+=p[k]*r.m;a.extra+=p[k]*(r.m-1);if(p[k+'_status']==='잠정채택')a.provisional++}}out[k]=a}return out;
}
function multiMinistry(params){
 const requestedSource=['summary','detail'].includes(params.get('source'))?params.get('source'):'all';
 main.innerHTML=heading('여러 부처 표기에 연결된 사업','연결된 부처의 원문 표기와 자료를 살펴보고, 부처별 합산에서 반복되는 사업 수와 금액을 확인합니다.')+`<div class="notice">이 화면의 ‘부처’는 <strong>자료 기재 부처</strong> 기준입니다. 약칭·정식 명칭은 합치지 않습니다. 실제로 서로 다른 부처인지, 공동 주관인지 또는 예산이 중복 편성됐는지를 확정한 결과는 아닙니다.</div><div class="budget-filters"><label>기재 문서<select id="multi-source"><option value="all" ${requestedSource==='all'?'selected':''}>요약서 또는 상세서</option><option value="summary" ${requestedSource==='summary'?'selected':''}>요약서 기재만</option><option value="detail" ${requestedSource==='detail'?'selected':''}>상세서 기재만</option></select></label><label>연결 형태<select id="multi-type"><option value="all">전체 복수 표기 연결</option><option value="together">한 문서에 복수 표기</option><option value="across">문서 간 다른 표기만</option></select></label><label>권역<select id="multi-region"><option value="">전체 권역</option>${D.regions.map(r=>`<option>${E(r.region)}</option>`).join('')}</select></label><label>사업·부처 검색<input id="multi-query" type="search" placeholder="사업명, ID, 자료 기재 부처"></label></div><div id="multi-summary"></div><div class="result-heading"><h2>연결 사업과 사업 자료</h2><label>정렬<select id="multi-sort"><option value="m">연결 표기 많은 순</option><option value="whole">전체 사업비 큰 순</option><option value="window">기간 투자액 큰 순</option><option value="national">국비 요구액 큰 순</option></select></label></div><div id="multi-projects"></div>`;
 let rows=[],page=1;
 function draw(){const source=document.querySelector('#multi-source').value,type=document.querySelector('#multi-type').value,region=document.querySelector('#multi-region').value,q=document.querySelector('#multi-query').value.trim().toLowerCase();
 const all=multipleMinistryProjects(D.projects,ministryRows,source);rows=all.filter(r=>(type==='all'||(type==='together'?r.together:!r.together))&&(!region||r.p.region===region)&&(!q||(r.p.title+' '+r.p.id+' '+r.labels.join(' ')).toLowerCase().includes(q)));
 const t=multipleMinistryTotals(rows),together=rows.filter(r=>r.together).length;
 document.querySelector('#multi-summary').innerHTML=`<div class="multi-scope"><strong>현재 조건에 맞는 ${N(t.unique)}개 고유 사업</strong><span>한 문서에 복수 표기 ${N(together)}건 · 문서 간 다른 표기만 ${N(t.unique-together)}건</span></div><div class="metrics multi-metrics"><div class="metric"><div class="label">고유 사업 수 · 사업당 1회</div><strong>${N(t.unique)}</strong><small>건</small></div><div class="metric"><div class="label">부처 표기별 합산 건수</div><strong>${N(t.repeated)}</strong><small>건</small></div><div class="metric"><div class="label">추가로 반복 집계되는 건수</div><strong>${N(t.extra)}</strong><small>건</small></div></div><div class="card table-wrap multi-totals"><table><thead><tr><th>예산 구분 · 억원</th><th class="num">사업당 한 번<br>기재 금액 부분합</th><th class="num">부처 표기별 반복 합산</th><th class="num">반복분 차이</th></tr></thead><tbody>${budgetFields.map(([k,label])=>{const a=t[k];return `<tr><th scope="row">${label}<span class="count-note">숫자 있음 ${a.known}건 · 잠정채택 포함 ${a.provisional}건</span></th><td class="num"><strong>${a.known?N(a.unique):'미확인'}</strong><span class="count-note">보류 ${a.held} · 기타 미확인 ${a.unknown}건 제외</span></td><td class="num"><strong>${a.known?N(a.repeated):'미확인'}</strong><span class="count-note">보류 ${a.heldRepeated} · 기타 미확인 ${a.unknownRepeated}회 제외</span></td><td class="num"><strong class="repeat-amount">${a.known?N(a.extra):'미확인'}</strong><span class="count-note">추가 제외: 보류 ${a.heldRepeated-a.held} · 미확인 ${a.unknownRepeated-a.unknown}회</span></td></tr>`}).join('')}</tbody></table></div><div class="notice amber">반복분 = 각 사업의 기재 금액 × (서로 다른 부처 표기 수 − 1). 동일한 표기가 요약서·상세서에 반복돼도 1개로 셉니다. 위 금액은 <strong>현재 목록의 사업들이 연결된 모든 부처 표기</strong>를 합산한 값이며, 신규 예산이나 실제 재원 중복액이 아닙니다. 보류·미확인 금액은 합산하지 않습니다.</div><details class="card multi-definition"><summary>문서 간 표기 차이는 어떻게 읽나요?</summary><p>예를 들어 요약서에 ‘산업부’, 상세서에 ‘산업통상부’만 기재된 사업은 ‘문서 간 다른 표기만’으로 표시합니다. 두 이름이 서로 다른 실제 부처라는 의미는 아닙니다. 한 문서 안에 여러 표기가 있어도 공동 주관 여부는 원문 표현을 확인해야 합니다.</p><p>상세서 연결 방식과 문단 위치는 각 사업에서 그대로 표시합니다. ‘제목만 연결’ 등 제한이 있는 경우도 해당 상태를 유지합니다.</p></details>`;
 page=1;drawProjects();
 }
 function drawProjects(){const sort=document.querySelector('#multi-sort').value;rows.sort((a,b)=>sort==='m'?b.m-a.m||a.p.id.localeCompare(b.p.id,'ko'):(b.p[sort]??-Infinity)-(a.p[sort]??-Infinity));const pages=Math.max(1,Math.ceil(rows.length/10));page=Math.min(page,pages);
 document.querySelector('#multi-projects').innerHTML=rows.slice((page-1)*10,page*10).map(r=>{const p=r.p;return `<article class="card multi-project"><div class="multi-project-head"><div><small>${E(p.id)} · ${E(p.region)}</small><h3><a href="${link(p,'graph')}">${E(p.title)} ↗</a></h3></div>${pill(r.together?'한 문서에 복수 표기':'문서 간 다른 표기만',r.together?'original':'unknown')}</div><div class="connection-chips">${r.labels.map(label=>`<a href="${hubLink('ministry',label,document.querySelector('#multi-source').value)}">${E(label)} <small>${[...new Set(r.records.filter(x=>x.label===label).map(x=>x.origin==='summary'?'요약서':'상세서'))].join('·')}</small> ↗</a>`).join('')}</div><p class="multi-count">${r.m}개 자료 기재 부처에 연결 · 사업당 1회 → 부처 표기별 ${r.m}회 · 추가 반복 ${r.m-1}회</p><div class="table-wrap"><table><thead><tr><th>예산 구분</th><th class="num">사업당 1회</th><th class="num">부처 표기별 ${r.m}회</th><th class="num">반복분 차이</th></tr></thead><tbody>${budgetFields.map(([k,label])=>{const known=p[k]!=null&&p[k+'_status']!=='보류';return `<tr><th>${label}<small class="count-note">${E(p[k+'_status']||'미확인')}</small></th><td class="num">${known?N(p[k]):'미확인'}</td><td class="num">${known?N(p[k]*r.m):'합계 제외'}</td><td class="num">${known?N(p[k]*(r.m-1)):'합계 제외'}</td></tr>`}).join('')}</tbody></table></div><details class="multi-original"><summary>부처 기재 내용과 출처 확인</summary>${['summary','detail'].filter(origin=>r.records.some(x=>x.origin===origin)).map(origin=>{const x=r.records.find(x=>x.origin===origin);return `<section><h4>${origin==='summary'?'요약서':'상세서'} 부처 항목</h4>${quote(x.raw)}${meta(x.source,x.location)}${origin==='detail'?`<p class="source-meta">상세 연결: ${E(p.detail_match)} · 자료번호: ${E(x.evidence||'미기재')}</p>`:''}</section>`}).join('')}<a class="button" href="${link(p,'graph')}">사업 관련 자료 전체 보기 →</a></details></article>`}).join('')||'<div class="empty">조건에 맞는 복수 부처 표기 연결 사업이 없습니다.</div>';
 document.querySelector('#multi-projects').insertAdjacentHTML('beforeend',`<div class="pagination"><button id="multi-prev" ${page===1?'disabled':''}>← 이전</button><span>${page} / ${pages} · ${N(rows.length)}개 사업</span><button id="multi-next" ${page===pages?'disabled':''}>다음 →</button></div>`);
 document.querySelector('#multi-prev').onclick=()=>{page--;drawProjects()};document.querySelector('#multi-next').onclick=()=>{page++;drawProjects()};
 }
 ['multi-source','multi-type','multi-region'].forEach(id=>document.getElementById(id).onchange=draw);document.querySelector('#multi-query').oninput=draw;document.querySelector('#multi-sort').onchange=()=>{page=1;drawProjects()};draw();
}

// All summaries use selected unique IDs and literal source ministry labels.
function selectionSummarySheets(projects,records){
 const ps=[...new Map(projects.map(p=>[p.id,p])).values()],labels=new Map(ps.map(p=>[p.id,new Set()]));
 records.forEach(r=>{if(labels.has(r.id)&&r.label)labels.get(r.id).add(r.label)});
 const metrics=[['whole','전체 사업비'],['window','2027~2032년 투자액'],['national','해당 기간 국비 요구액']];
 const headers=['집계 구분','사업 수 (건·중복 포함 시 회)','예산 항목','집계 가능 금액 (억원·부분합)','금액 포함 건수','잠정채택 건수 (금액 포함 중)','보류 건수 (금액 제외)','기타 미확인 건수 (금액 제외)','집계 기준'];
 function rows(name,items,note){return metrics.map(([key,title])=>{let sum=0,known=0,provisional=0,held=0,unknown=0;for(const p of items){const status=String(p[key+'_status']||'');if(status.includes('보류'))held++;else if(typeof p[key]==='number'&&Number.isFinite(p[key])){known++;sum+=p[key];if(status.includes('잠정'))provisional++}else unknown++}return [name,items.length,title,known?sum:null,known,provisional,held,unknown,note]})}
 const linked=ps.filter(p=>labels.get(p.id).size),unlinked=ps.filter(p=>!labels.get(p.id).size),repeat=linked.flatMap(p=>Array(labels.get(p.id).size).fill(p)),extra=linked.flatMap(p=>Array(labels.get(p.id).size-1).fill(p));
 const make=(name,r)=>({name,headers,widths:[34,24,29,28,19,27,25,30,85],rows:r});
 const overall=make('선택요약',[
  ...rows('선택 전체 · 중복 제거',ps,'사업번호당 1건. 부처 연결이 없는 사업도 포함.'),
  ...rows('부처 연결 있음 · 중복 제거',linked,'자료 기재 부처가 1개 이상 연결된 사업번호당 1건.'),
  ...rows('부처 연결 없음 · 중복 제거',unlinked,'부처별 합계에 들어가지 않는 선택 사업. 소관부처가 없다는 뜻은 아님.'),
  ...rows('부처별 반복 합계',repeat,'사업별 서로 다른 자료 기재 부처 수만큼 반복. 동일 표기의 요약서·상세서 중복은 제거.'),
  ...rows('추가 반복분',extra,'부처별 반복 합계 − 부처 연결 있음 중복 제거 합계. 실제 중복 재원 또는 추가 예산이 아님.')
 ]);
 const regionNames=[...new Set(ps.map(p=>p.region||'권역 미기재'))].sort((a,b)=>a.localeCompare(b,'ko'));
 const ministryNames=[...new Set([...labels.values()].flatMap(s=>[...s]))].sort((a,b)=>a.localeCompare(b,'ko'));
 return [overall,make('권역별요약',regionNames.flatMap(name=>rows(name,ps.filter(p=>(p.region||'권역 미기재')===name),'권역 내 사업번호당 1건. 권역 간 합계는 선택 전체 중복 제거 합계와 일치.'))),make('부처별요약',ministryNames.flatMap(name=>rows(name,ps.filter(p=>labels.get(p.id).has(name)),'요약서·상세서 원문 표기 기준. 부처 내 ID 중복 제거, 부처 간 반복 포함. 약칭·정식 명칭 통합 안 함.'))),make('사업구분별요약',TYPE_GROUPS.flatMap(name=>rows(name,ps.filter(p=>projectType(p)===name),'교통시설·이동서비스는 교통으로 별도 집계. 네 구분 간 중복 없음.')))];
}

let selectedSummaryGroup='region',selectedSummaryFilter=null;
function selectedSummaryTable(sheet,repeated=false,kind=null){
 const groups=[];for(let i=0;i<sheet.rows.length;i+=3)groups.push(sheet.rows.slice(i,i+3));
 return `<div class="table-wrap"><table class="selection-summary-table"><thead><tr><th scope="col">집계 구분</th><th scope="col">사업 수</th><th scope="col">전체 사업비</th><th scope="col">2027~2032년 투자액</th><th scope="col">해당 기간 국비 요구액</th></tr></thead><tbody>${groups.map(rs=>`<tr><th scope="row">${kind?`<button class="summary-drill" data-summary-name="${E(rs[0][0])}" data-summary-kind="${kind}" aria-pressed="${selectedSummaryFilter?.kind===kind&&selectedSummaryFilter?.name===rs[0][0]}" aria-controls="selected-drilldown">${E(rs[0][0])}<span>선택 사업 ${N(rs[0][1])}건 보기 →</span></button>`:E(rs[0][0])}</th><td class="num">${N(rs[0][1])}<small>${repeated||rs[0][0]==='부처별 반복 합계'||rs[0][0]==='추가 반복분'?'회':'건'}</small></td>${rs.map(r=>`<td class="num"><strong>${r[3]===null?'—':N(r[3])}</strong><span class="summary-known">금액 포함 ${N(r[4])} · 잠정채택 ${N(r[5])}</span><span class="summary-pending ${r[6]||r[7]?'has-pending':''}">보류 ${N(r[6])} · 기타 미확인 ${N(r[7])}</span></td>`).join('')}</tr>`).join('')||'<tr><td colspan="5">집계할 부처 연결이 없습니다.</td></tr>'}</tbody></table></div>`;
}
function refreshSelectedSummary(){
 const holder=document.querySelector('#selected-summary');if(!holder)return;
 const ps=D.projects.filter(p=>selectedProjects.has(p.id)),signature=JSON.stringify([ps.map(p=>p.id),selectedSummaryGroup,selectedSummaryFilter]);if(holder.dataset.signature===signature)return;holder.dataset.signature=signature;
 if(!ps.length){holder.innerHTML='<section class="card selection-summary"><h2>선택 사업 요약</h2><p>사업을 담으면 권역별·부처별 사업 수와 예산을 여기에서 바로 확인할 수 있습니다.</p><a class="button" href="#projects">사업 검색에서 담기 →</a></section>';return}
 const sheets=selectionSummarySheets(ps,ministryRows);
 holder.innerHTML=`<section class="card selection-summary" aria-labelledby="selected-summary-title"><div class="summary-heading"><div><p class="eyebrow">선택한 ${N(ps.length)}개 사업만 집계</p><h2 id="selected-summary-title">선택 사업 요약</h2></div><span>금액 단위: 억원 · 부분합</span></div><p>엑셀 요약과 같은 기준입니다. 사업을 담거나 선택을 해제하면 바로 갱신됩니다.</p>${selectedSummaryTable(sheets[0])}<div class="summary-explainer"><p><strong>중복 제거:</strong> 사업번호당 한 번 집계합니다. 부처 연결 없는 사업도 전체 합계에 포함합니다.</p><p><strong>부처별 반복 합계:</strong> 서로 다른 자료 기재 부처마다 한 번씩 집계합니다. 추가 반복분은 부처 연결 사업의 중복 제거 합계와의 차이이며, 실제 중복 재원이나 추가 예산을 뜻하지 않습니다.</p><p><strong>보류·기타 미확인:</strong> 금액 합계에서 제외하고 건수로 표시합니다. 포함 가능한 금액이 없으면 —로 표시하며, 실제 0원과 구분합니다. 잠정채택은 금액 포함 건수의 일부입니다. 반복 합계의 건수도 반복을 포함합니다.</p></div></section><section class="card selection-summary" aria-labelledby="selected-group-title"><div class="summary-heading"><h2 id="selected-group-title">${selectedSummaryGroup==='region'?'권역별':'자료 기재 부처별'} 요약</h2><div class="summary-switch" role="group" aria-label="요약 분류"><button data-summary-group="region" aria-pressed="${selectedSummaryGroup==='region'}">권역별</button><button data-summary-group="ministry" aria-pressed="${selectedSummaryGroup==='ministry'}">부처별</button></div></div><p>${selectedSummaryGroup==='region'?'권역별 사업 수·예산의 합은 선택 전체의 중복 제거 합계와 같습니다.':'요약서·상세서 원문 표기 기준입니다. 같은 표기의 문서 간 중복은 제거하며, 약칭·정식 명칭은 합치지 않습니다. 각 부처 안에서는 사업당 1건, 부처 간 합계에는 반복이 포함됩니다.'}</p><p class="summary-click-help">권역 또는 부처 이름을 누르면 해당하는 선택 사업만 아래에 펼쳐집니다.</p>${selectedSummaryTable(sheets[selectedSummaryGroup==='region'?1:2],false,selectedSummaryGroup)}<div id="selected-drilldown">${selectedDrilldown(ps)}</div></section>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-summary-group]');if(!b)return;selectedSummaryGroup=b.dataset.summaryGroup;selectedSummaryFilter=null;refreshSelectedSummary();document.querySelector(`[data-summary-group="${selectedSummaryGroup}"]`)?.focus()});

function selectedDrilldownProjects(ps,filter,records){
 if(!filter)return [];
 const ids=new Set(records.filter(r=>r.label===filter.name).map(r=>r.id));
 return [...new Map(ps.filter(p=>filter.kind==='region'?(p.region||'권역 미기재')===filter.name:ids.has(p.id)).map(p=>[p.id,p])).values()];
}
function selectedDrilldown(ps){
 if(!selectedSummaryFilter)return '';
 const f=selectedSummaryFilter,rows=selectedDrilldownProjects(ps,f,ministryRows);
 return `<section class="selected-drill-panel" aria-labelledby="selected-drill-title"><div class="summary-heading"><div><small>현재 선택한 사업 안에서만 보기</small><h3 id="selected-drill-title" tabindex="-1">${E(f.name)} · 선택 사업 ${N(rows.length)}건</h3></div><div class="actions"><button class="primary" data-export-drill ${exportBusy||!rows.length?'disabled':''}>펼친 ${N(rows.length)}개 사업만 엑셀 ↓</button><button data-summary-close>목록 닫기</button></div></div><p>전체 선택 ${N(ps.length)}건 중 ${N(rows.length)}건입니다. 이곳의 다운로드 버튼은 펼친 사업만 담습니다. 전체 선택은 유지됩니다.</p><p>요약·사업 자료·공개자료·자료 확인 현황을 항상 함께 넣습니다. 부처별 요약은 해당 사업에 연결된 모든 자료 기재 부처를 포함합니다.</p><p data-drill-export-status role="status">${E(exportStatus)}</p><div class="selected-drill-grid">${rows.map(p=>`<article class="selected-drill-project"><small>${E(p.region)} · ${E(p.id)}</small><h4><a href="${link(p,'graph')}">${E(p.title)} →</a></h4><p>사업 자료 ${N(p.source_count)}개 · ${E(p.detail_match||'상세서 연결 미확인')}</p><p class="source-meta">공개자료 확인: ${E(p.public_status||'미확인')}</p><details><summary>자료 기재 부처·관련 자료</summary>${f.kind==='ministry'?ministryRows.filter(r=>r.id===p.id&&r.label===f.name).map(r=>`<p><b>${r.origin==='summary'?'요약서':'상세서'}</b> ${E(r.raw)}</p><small>${E(r.source)} · ${E(r.location)} · 자료번호 ${E(r.evidence||'미기재')}</small>`).join(''):`<p>요약서: ${E(p.summary_ministry||'미기재')}</p><p>상세서: ${E(p.detail_ministry||'미기재')}</p>`}</details><a class="button" href="${link(p,'graph')}">자료 및 확인 현황 보기 →</a></article>`).join('')||'<p class="empty">현재 선택한 사업 중 이 항목에 해당하는 사업이 없습니다.</p>'}</div></section>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-summary-name],[data-summary-close]');if(!b)return;
 if(b.hasAttribute('data-summary-close')){selectedSummaryFilter=null;refreshSelectedSummary();document.querySelector('[data-summary-group][aria-pressed=true]')?.focus();return}
 selectedSummaryFilter={kind:b.dataset.summaryKind,name:b.dataset.summaryName};refreshSelectedSummary();const title=document.querySelector('#selected-drill-title');title?.focus({preventScroll:true});title?.scrollIntoView({behavior:'smooth',block:'start'});
});

document.addEventListener('click',e=>{if(!e.target.closest('[data-export-drill]')||!selectedSummaryFilter)return;e.preventDefault();exportSelection({...selectedSummaryFilter})});

const selectionKey='regional-evidence-selected-projects',selectedProjects=new Set();let exportBusy=false,includeExportSources=true,exportStatus='';
try{const saved=JSON.parse(localStorage.getItem(selectionKey)||'[]');if(Array.isArray(saved))saved.forEach(id=>{if(P.has(id))selectedProjects.add(id)})}catch{}
