function attachSelectionControls(){let changed=false;
 document.querySelectorAll('.results-table tbody tr').forEach(row=>{if(row.dataset.selectionReady)return;const a=row.querySelector('.project-title a');if(!a)return;const id=decodeURIComponent(a.getAttribute('href').split('/')[1]||'');if(!P.has(id))return;row.dataset.selectionReady='1';const td=document.createElement('td');td.innerHTML=selectionControl(id);row.prepend(td);changed=true});const th=document.querySelector('.results-table thead tr');if(th&&!th.dataset.selectionReady){th.dataset.selectionReady='1';th.insertAdjacentHTML('afterbegin','<th>選択</th>'.replace('選択','선택'));changed=true}
 document.querySelectorAll('.hub-project-card').forEach(a=>{if(a.dataset.selectionReady)return;const id=decodeURIComponent(a.getAttribute('href').split('/')[1]||'');if(!P.has(id))return;a.dataset.selectionReady='1';const wrap=document.createElement('div');wrap.className='selection-card-wrap';a.before(wrap);wrap.innerHTML=selectionControl(id);wrap.append(a);changed=true});
 document.querySelectorAll('.multi-project').forEach(el=>{if(el.dataset.selectionReady)return;const a=el.querySelector('h3 a');if(!a)return;const id=decodeURIComponent(a.getAttribute('href').split('/')[1]||'');if(!P.has(id))return;el.dataset.selectionReady='1';el.insertAdjacentHTML('afterbegin',selectionControl(id));changed=true});
 document.querySelectorAll('.project-head,.relationship-map').forEach(el=>{if(el.dataset.selectionReady)return;const routeId=location.hash.split('/')[1]?.split('?')[0],id=routeId?decodeURIComponent(routeId):D.projects[0].id;if(!P.has(id))return;el.dataset.selectionReady='1';el.insertAdjacentHTML('afterbegin',selectionControl(id));changed=true});
 const search=document.querySelector('#search-form');if(search&&!document.querySelector('#selection-search-tools')){search.insertAdjacentHTML('afterend','<div id="selection-search-tools" class="selection-search-tools"><button data-select-results>검색 결과 전체 선택</button><button data-select-visible>현재 페이지 선택</button><a class="button" href="#selected">선택 사업 관리 →</a><small>선택 목록에 추가할 때 사용하세요.</small></div>');changed=true}
 if(changed)refreshSelection();
}
function sourceChunks(v){const s=String(v??''),out=[];let i=0;while(i<s.length){let end=Math.min(i+30000,s.length);if(end<s.length&&/[\uD800-\uDBFF]/.test(s[end-1]))end--;out.push(s.slice(i,end));i=end}return out.length?out:['']}
function selectionSheets(ps,packets,withSources){
 ps=[...new Map(ps.map(p=>[p.id,p])).values()];
 const sheets=[{name:'선택사업',headers:['사업번호','권역','구분','사업명','요약서 부처 원문','상세서 부처 원문','전체 사업비 (억원)','전체 사업비 상태','2027~2032 투자액 (억원)','기간 투자액 상태','해당 기간 국비 요구액 (억원)','국비 요구액 상태','요약서 사업기간','상세서 사업기간','상세서 연결 방식','공개자료 확인 상태','요약서 파일','요약서 위치','상세서 파일','상세서 위치','사업 내용','사업 상세 링크'],widths:[25,14,14,65,35,45,22,17,24,17,26,17,25,35,24,45,55,30,55,30,90,60],rows:ps.map(p=>[p.id,p.region,p.category,p.title,p.summary_ministry,p.detail_ministry,p.whole,p.whole_status,p.window,p.window_status,p.national,p.national_status,p.period,p.detail_period,p.detail_match,p.public_status,p.summary_source,p.summary_location,p.detail_source,p.detail_location,p.summary_body,new URL(link(p),window.location.href).href])}];
 sheets.unshift(...selectionSummarySheets(ps,ministryRows));sheets.push(typeClassificationSheet(ps));
 if(withSources){const ids=new Set(ps.map(p=>p.id));sheets.push({name:'부처기재내역',headers:['사업번호','부처 표기','기재 문서','자료 기재 부처 항목','파일','위치','자료번호','상세서 연결 상태'],widths:[25,25,15,70,60,35,25,25],rows:ministryRows.filter(r=>ids.has(r.id)).map(r=>[r.id,r.label,r.origin==='summary'?'요약서':'상세서',r.raw,r.source,r.location,r.evidence,r.detail_match])});
 sheets.push({name:'사업자료',headers:['사업번호','자료번호','항목','파일','위치','인용 부분','자료 발췌','자료 확인 현황'],widths:[25,18,22,60,30,15,110,30],rows:packets.flatMap(d=>d.evidence.flatMap(e=>sourceChunks(e.excerpt).map((chunk,i,a)=>[d.id,e.evidence_id,e.field,e.source,e.location,`${i+1}/${a.length}`,chunk,'원문 기재 · 실제 집행·승인 미확인'])))});
 sheets.push({name:'공개자료',headers:['사업번호','출처 ID','자료명','URL','발행 도메인','확인일','열람 수준','사업과 관계','발췌 부분','발췌 내용','확인 범위','동일사업 여부'],widths:[25,18,65,90,30,18,60,45,15,100,80,25],rows:packets.flatMap(d=>d.sources.flatMap(s=>sourceChunks(s.excerpt).map((chunk,i,a)=>[d.id,s.source_id,s.title,s.url,s.publisher_domain,s.checked,s.read_level,d.public.find(r=>r.source_id===s.source_id)?.relation||'기존 참고자료',`${i+1}/${a.length}`,chunk,s.field_scope,'미확인'])))});
 }
 sheets.push({name:'읽기안내',headers:['항목','내용'],widths:[32,110],rows:[['사업구분 기준',TYPE_SCOPE],['사업구분 금액',TYPE_BUDGET_NOTE],['분석 기준일','2026-10-30'],['선택 사업 수',ps.length],['내보낸 시각',new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' (한국시간)'],['예산 단위','억원. 전체 사업비·2027~2032년 투자액·해당 기간 국비 요구액을 구분합니다.'],['빈칸과 보류','금액 빈칸은 미확인입니다. 0으로 치환하지 않았습니다. 상태 열의 보류·잠정채택 등을 함께 확인하세요.'],['부처 표기','요약서·상세서 원문 기준이며 실제 소관 확정이 아닙니다. 약칭과 정식 명칭은 통합하지 않았습니다.'],['공개자료','검색 발췌와 원문 열람 수준은 자료별 열에 표시합니다. 연결이 동일사업·동일재원을 의미하지 않습니다.'],['자료 발췌','셀 글자 수 제한을 넘는 긴 인용은 순번을 붙여 여러 행으로 나눕니다.'],['자료 포함',withSources?'포함':'기본정보·요약만'],['요약 집계','선택요약·권역별요약·부처별요약·사업구분별요약·사업구분내역은 항상 포함하며 다운로드 시점의 고정 집계입니다. 사업 수는 예산 항목마다 반복되므로 세 예산 행의 사업 수를 더하지 마세요.'],['부분합과 미확인','집계 가능 금액은 보류와 기타 미확인을 제외한 부분합입니다. 보류는 상태에 보류가 표시된 항목, 기타 미확인은 보류 외 금액 미확인 항목입니다. 미확인 금액은 산출하지 않고 건수로 표시합니다. 포함 가능한 금액이 전혀 없으면 부분합도 빈칸입니다. 잠정채택은 포함 금액 중 별도 건수로 표시합니다.'],['반복 합계','부처별 반복 합계는 서로 다른 자료 기재 부처마다 사업을 한 번씩 집계합니다. 추가 반복분은 부처 연결 사업의 중복 제거 합계와의 차이이며 실제 중복 재원이나 추가 예산을 뜻하지 않습니다. 부처 연결 없는 사업은 전체 합계에만 포함합니다.'],['사업 중복','사업번호별 한 번만 내보냅니다. 부처기재내역·사업자료 시트에는 한 사업의 여러 자료가 반복 행으로 나타납니다.']]});return sheets;
}
async function exportSelection(scope=null){if(exportBusy)return;const selected=D.projects.filter(p=>selectedProjects.has(p.id)),ps=scope?.kind==='search'?[...new Set(scope.ids)].map(id=>P.get(id)).filter(Boolean):scope?selectedDrilldownProjects(selected,scope,ministryRows):selected,withSources=scope?true:includeExportSources;if(!ps.length)return;exportBusy=true;exportStatus='자료 준비 중…';refreshSelection();try{const packets=[];if(withSources){for(let i=0;i<ps.length;i+=6){const batch=await Promise.all(ps.slice(i,i+6).map(p=>packet(p.id)));packets.push(...batch);exportStatus=`자료 불러오기 ${Math.min(i+6,ps.length)} / ${ps.length}`;refreshSelection();await new Promise(r=>setTimeout(r,0))}}const sheets=selectionSheets(ps,packets,withSources);if(scope?.kind==='search'){sheets.push({name:'검색조건',headers:['조건','설정값'],widths:[32,100],rows:[...scope.criteria,['검색 결과 수',ps.length],['다운로드 범위','버튼을 누른 시점의 검색 결과 전체. 페이지 구분 없이 사업번호별 1건.'],['자료 범위','사업 자료·공개 참고자료·확인 현황을 포함합니다. 부처별 요약은 해당 사업에 기재된 모든 부처를 집계합니다.']]})}else if(scope)sheets.find(s=>s.name==='읽기안내').rows.push(['내보내기 범위',(scope.kind==='region'?'권역':'자료 기재 부처')+': '+scope.name+' · 다운로드 버튼을 누른 시점의 펼친 선택 사업 '+ps.length+'건'],['부처별 요약 범위','이 파일에 담긴 사업에 연결된 모든 자료 기재 부처를 집계합니다. 눌렀던 부처만으로 제한하지 않습니다.'],['자료 포함 범위','펼친 사업만 내보내기에는 사업·참고자료와 자료 확인 현황이 항상 포함됩니다.']);exportStatus='엑셀 파일 생성 중…';refreshSelection();await new Promise(r=>setTimeout(r,0));const blob=window.AtlasXlsx.workbook(sheets),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`${scope?.kind==='search'?'검색결과':scope?'펼친사업_'+(scope.kind==='region'?'권역':'부처')+'_'+scope.name.replace(/[\\/:*?"<>|]/g,'_'):'선택사업'}_${ps.length}건_${new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})}.xlsx`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);exportStatus=`${scope?scope.name+' · ':''}${ps.length}개 사업의 엑셀 다운로드를 시작했습니다.`}catch(e){exportStatus='내려받기에 실패했습니다. 선택은 유지됩니다. 다시 시도해 주세요.';console.error('Excel export failed',e)}finally{exportBusy=false;refreshSelection()}}
